var e=JSON.parse(`{"wrist-circles":{"name":"دوائر الرسغين","description":"قف منتصبًا مع إرخاء المرفقين وضع الساعدين أمامك. ارسم دوائر بطيئة بكلا الرسغين، أربع عدّات في اتجاه وأربع في الاتجاه الآخر، مع إبقاء الأصابع مرتخية.","goodFor":"يُسخّن الرسغين والساعدين اللذين يقومان بمعظم العمل في كل أداة.","alignmentCues":["المرفقان ثابتان؛ الرسغان فقط يتحركان.","حافظ على الدوائر كبيرة وسلسة."],"commonMistakes":["الاستعجال في الدوائر حتى تتحول إلى نقرات سريعة."]},"arm-circles":{"name":"دوائر الذراعين","description":"القدمان بعرض الوركين، والذراعان ممدودتان. أرجح الذراعين في دوائر أمامية كبيرة لأربع عدّات، ثم للخلف لأربع، مع ترك لوحي الكتف ينزلقان.","goodFor":"يفتح الكتفين لتدوير العصا والعمل بالطوق فوق الرأس.","alignmentCues":["يبقى القفص الصدري للأسفل أثناء مرور الذراعين فوق الرأس.","ازفر عند الترجيح للأسفل."]},"shoulder-rolls":{"name":"تدوير الكتفين","description":"الذراعان مرتخيتان بجانبك. ارفع الكتفين نحو الأذنين، ثم دوّرهما للخلف وللأسفل، وكرر في حلقة بطيئة.","goodFor":"يحرر التوتر الذي يجعل الرميات متيبسة وقصيرة."},"neck-rolls":{"name":"أنصاف دوائر الرقبة","description":"أنزل الذقن نحو الصدر ومرره ببطء من كتف إلى كتف في نصف دائرة. لا تدع الرأس يميل للخلف.","goodFor":"يريح الرقبة قبل النظر لأعلى نحو الرميات لفترات طويلة.","avoidIf":["إصابة في الرقبة أو دوخة عند تحريك الرأس."]},"hip-circles":{"name":"دوائر الوركين","description":"اليدان على الوركين، والركبتان مرتخيتان. دوّر الوركين ببطء في اتجاه لمازورين وفي الاتجاه الآخر لمازورين، مع إبقاء الرأس مستويًا.","goodFor":"يهيئ الوركين لتدوير الطوق على الخصر والجسم للflow."},"torso-twists":{"name":"لف الجذع","description":"القدمان متباعدتان، والذراعان مرتخيتان. أدر القفص الصدري يمينًا ويسارًا ودع الذراعين تتأرجحان وتلتفان حولك مثل أكمام فارغة.","goodFor":"يوقظ الدوران لنسج العصا وتمريرات الطوق."},"knee-bounce":{"name":"ارتداد الركبتين","description":"قف والقدمان تحت الوركين وارتد بلطف عبر الركبتين على كل نبضة، مع تأرجح الذراعين بحرية. اعثر على الموسيقى في ساقيك.","goodFor":"يضع النبض في جسمك قبل أن تلتقط أي أداة."},"one-ball-toss":{"name":"رمي كرة واحدة","description":"أمسك كرة واحدة في يدك اليمنى عند ارتفاع الخصر. اسحبها للداخل، ثم ارمها في قوس يبلغ ذروته فوق مستوى العين بقليل ويسقط في اليد اليسرى. ارمها مرة أخرى بنفس الطريقة. أبقِ عينيك على قمة القوس، لا على يديك.","goodFor":"يبني القوس الذي تتكون منه كل أنماط التنسيق.","alignmentCues":["المرفقان بجانبك، والساعدان مستويان.","القمة بنفس الارتفاع في كل رمية.","التقط عند ارتفاع الخصر ودع اليد تمتص قليلًا."],"commonMistakes":["الرمي للأمام بحيث تضطر للخطو خلف الكرة.","النظر إلى اليدين بدلًا من القمة."]},"two-ball-exchange":{"name":"تبادل كرتين","description":"كرة في كل يد. ارمِ الكرة اليمنى في قوسها؛ وعندما تبلغ الذروة، ارمِ الكرة اليسرى تحتها من الداخل. التقط الاثنتين وتوقف لحظة. ثم ابدأ باليد اليسرى.","goodFor":"يعلّم التبادل: الرمية الثانية تأتي عندما تبلغ الأولى ذروتها.","alignmentCues":["الرمية الثانية عند الذروة، وليس مبكرًا أبدًا.","ارمِ الكرة الثانية داخل الأولى."],"commonMistakes":["تمرير الكرة الثانية عبر الجسم بدلًا من رميها.","رمي الكرتين معًا في نفس الوقت."]},"cascade":{"name":"Cascade بثلاث كرات","description":"كرتان في اليد اليمنى وواحدة في اليسرى. ارمِ من اليمنى؛ وعندما تصل للقمة ارمِ من اليسرى؛ وعندما تصل تلك للقمة ارمِ من اليمنى مجددًا. كل رمية تكون على الإيقاع، وتتقاطع إلى اليد الأخرى في قوس على شكل 8.","goodFor":"النمط الأساسي في التمرير.","modifications":["تدرّب على الـ flash: ثلاث رميات، ثلاث التقاطات، ثم توقف."],"deepen":["مرّر بإيقاع أسرع مع قمم أقل.","عُدّ 20 التقاطة دون سقوط."],"alignmentCues":["ارمِ من الداخل، والتقط من الخارج.","القمم متساوية، على ارتفاع العينين.","قف مقابل الحائط إذا كنت تستمر في التقدم للأمام."],"commonMistakes":["الرمي للأمام والجري خلف النمط.","التسرّع بمجرد أن تخطئ رمية واحدة."]},"reverse-cascade":{"name":"كاسكيد عكسي","description":"الـ cascade مقلوبًا: تُرمى كل كرة من الخارج، فوق قمة النمط، ثم تسقط في المنتصف إلى اليد الأخرى.","goodFor":"يدرّب الرميات من الخارج ويفتح حيلًا مثل Mills Mess.","alignmentCues":["الرميات تلتف فوق الكرة القادمة.","التقط في المنتصف."]},"siteswap-423":{"name":"423","description":"نمط بثلاث كرات: رمية ذاتية عالية (4)، كرة محمولة (2)، ثم رمية cascade (3). الـ 4 تصعد على نفس الجانب؛ والـ 2 تُحمل ببساطة لمدة نبضة.","goodFor":"أول حيلة siteswap لك: تعلّم الرميات العالية والثبات."},"siteswap-441":{"name":"441","description":"رميتان عاليتان تبقى كل منهما على جانبها (4, 4) تتبعهما zip سريع عبر الجسم (1) من يد إلى يد.","goodFor":"يبني التوقيت بين الرميات العالية والتمريرات السريعة."},"two-in-one":{"name":"كرتان في يد واحدة","description":"مرّر كرتين في يد واحدة في أعمدة متجاورة أو دوائر صغيرة للخارج، رمية واحدة كل نبضتين. تدرّب على كل يد.","goodFor":"اللبنة الأساسية لتمرير أربع كرات."},"siteswap-531":{"name":"531","description":"رمية متقاطعة عالية جدًا (5)، ورمية cascade (3)، وzip سريع (1). الـ 5 تصعد بينما تستمر الكرتان الأخريان في العمل تحتها.","goodFor":"التحكم في الارتفاع وحيلة استعراضية بثلاث كرات."},"shower":{"name":"Shower بثلاث كرات","description":"تتحرك الكرات في دائرة: اليد اليمنى ترمي كل كرة عاليًا إلى اليسرى، واليد اليسرى تمرّر كل واحدة مباشرة إلى اليمنى.","goodFor":"نمط دائري كلاسيكي؛ يدرّب التمريرات السريعة من يد إلى يد."},"mills-mess":{"name":"Mills Mess","description":"cascade بثلاث كرات حيث تستمر الذراعان في التقاطع وفك التقاطع، بحيث تأتي كل رمية من الجانب المعاكس للجسم. مسارات الكرات ترسم نمطًا متشابكًا.","goodFor":"حيلة مشهورة تُبهر الجمهور وتصقل التناسق."},"four-ball-fountain":{"name":"Fountain بأربع كرات","description":"كل يد تمرّر كرتين في عمودها الخاص، وتتبادل اليدان الرمي بحيث لا يتقاطع النمط أبدًا.","goodFor":"أول نمط بأربع كرات لك."},"sync-fountain":{"name":"نافورة متزامنة","description":"أربع كرات مع رمي كلتا اليدين في اللحظة نفسها تمامًا، كل واحدة إلى جانبها.","goodFor":"يبني التناظر ويؤدي إلى حيل sync."},"five-ball-cascade":{"name":"Cascade بخمس كرات","description":"الكاسكيد بخمس كرات: رميات عالية وسريعة في نمط تقاطعي طويل. توقّع شهورًا من التدريب.","goodFor":"إنجاز بارز للاعبين المتفانين."},"staff-wheel-spin":{"name":"دوران العجلة بيدين","description":"أمسك العصا من المنتصف بكلتا يديك، راحتا اليدين للأسفل، عند ارتفاع الصدر. أدِرها بجانبك مثل عجلة بنقل الدوران بين اليدين، مع إبقائها بجانب جسمك.","goodFor":"أول دوران للعصا؛ يبني القبضة ودوران المعصم.","alignmentCues":["تبقى العصا موازية لجسمك، دون أي ميل.","قبضة ناعمة: دعها تتدحرج بين الأصابع."],"props":["عصا"],"commonMistakes":["الضغط بقوة حتى يتوقف الدوران.","إمالة المستوى إلى الأمام."]},"staff-front-spin":{"name":"الطاحونة الأمامية","description":"أدِر العصا أمامك مثل مروحة، في مستوى الجدار، ومرّرها بسلاسة من يد إلى يد حول مركزها.","goodFor":"يضيف مستوى الجدار وتمرير اليد تلو الأخرى.","props":["عصا"]},"staff-figure-8":{"name":"نسج الرقم 8","description":"أدِر العصا في مستوى العجلة على جانبك الأيمن، ثم اعبرها إلى جانبك الأيسر وأدِرها هناك، راسمًا رقم 8 أمامك.","goodFor":"يربط جانبي الجسم؛ العمود الفقري لتدفق العصا.","alignmentCues":["بدّل الجانبين عندما تتجاوز الأطراف الأرض.","أدِر جذعك قليلًا مع كل جانب."],"props":["عصا"]},"staff-pass-through":{"name":"التمرير العابر","description":"أدِر في مستوى الجدار لكن أفلت كل نصف دورة: تطلق يد العصا وتلتقطها اليد الأخرى من المركز، فتمر العصا بين يديك.","goodFor":"يعلّم توقيت الإفلات والالتقاط.","props":["عصا"]},"staff-one-hand-spin":{"name":"دوران بيد واحدة","description":"أدِر العصا أمامك بيد واحدة، ودحرجها فوق ظهر اليد وبين الأصابع. تدرّب بكلتا اليدين.","goodFor":"قوة الأصابع والمعصم؛ تحرّر اليد الأخرى للحيل.","props":["عصا"]},"staff-helicopter":{"name":"الهليكوبتر فوق الرأس","description":"ارفع العصا فوق رأسك وأدِرها أفقيًا في مستوى الأرض بيد واحدة، مثل شفرات الهليكوبتر.","goodFor":"يقدّم مستوى الأرض.","props":["عصا"]},"staff-butterfly":{"name":"الفراشة","description":"أدِر أمامك، ثم اطوِ العصا خلف كتفك وأخرجها، بالتناوب بين الأمام والخلف على كل جانب مثل الأجنحة.","goodFor":"مرونة الكتف وانتقال سلس من الأمام إلى الخلف.","props":["عصا"]},"staff-behind-back-pass":{"name":"تمرير خلف الظهر","description":"مرّر العصا الدائرة من يد إلى الأخرى خلف ظهرك عند أدنى نقطة في الدوران، ثم أعِدها إلى الأمام.","goodFor":"التفافات الجسم وتمريرات استعراضية.","props":["عصا"]},"staff-isolation":{"name":"عزل العصا","description":"أمسك العصا قرب أحد طرفيها وحرّك يدك في دائرة حول مركز العصا، بحيث يبدو المركز ثابتًا في الهواء بينما تدور العصا حوله.","goodFor":"عمل الإيهام ومسارات يد دقيقة.","props":["عصا"]},"staff-antispin-flower":{"name":"أنتيسبين بأربع بتلات","description":"حرّك يدك في اتجاه بينما تدور العصا في الاتجاه المعاكس بثلاثة أضعاف السرعة، فترسم العصا زهرة بأربع بتلات.","goodFor":"زهرة VTG المميزة؛ تحكّم عميق في التوقيت.","props":["عصا"]},"staff-neck-roll":{"name":"دحرجة على الرقبة","description":"أفلت العصا على ظهر كتفيك ودعها تتدحرج عبر الرقبة إلى اليد الأخرى. ابدأ ببطء بعصا مبطّنة.","goodFor":"Contact staff: العصا تتحرك على الجسم دون استخدام اليدين.","avoidIf":["ألم في الرقبة."],"props":["عصا"]},"hoop-waist":{"name":"تدوير الهولا هوب على الخصر","description":"قف بقدم واحدة أمام الأخرى قليلًا. ضع الهولا هوب على أسفل ظهرك، ارمِه حول خصرك وادفع البطن للأمام والخلف (وليس في دوائر) في كل مرة يمر فيها الهولا هوب أمامك.","goodFor":"أول مهارة بالهولا هوب؛ تبني إيقاع الجذع.","modifications":["استخدم هولا هوب أكبر وأثقل: يدور ببطء أكثر."],"alignmentCues":["تأرجح من الأمام إلى الخلف، وليس في دوائر.","ادفع الهولا هوب عند مروره على بطنك."],"props":["طوق"],"commonMistakes":["تدوير الوركين مثل راقصة الهولا.","هولا هوب صغير أو خفيف جدًا."]},"hoop-hand-spin":{"name":"تدوير الهولا هوب باليد","description":"أمسك الهولا هوب أمامك ويدك داخله، والإبهام للأعلى. ادفعه ليدور حول غشاء يدك، مع إبقاء الهولا هوب مستويًا أمامك.","goodFor":"أساس الهولا هوب خارج الجسم.","props":["طوق"]},"hoop-chest":{"name":"تدوير الهولا هوب على الصدر","description":"ارفع ذراعيك فوق رأسك ودوّر الهولا هوب حول الصدر، مع تأرجح القفص الصدري من الأمام إلى الخلف وإبقاء الوركين هادئين.","goodFor":"يعزل القفص الصدري ويبني تحكّم الجزء العلوي من الجسم.","props":["طوق"]},"hoop-lasso":{"name":"لاسو","description":"أمسك الهولا هوب فوق رأسك ودوّره مستويًا فوق رأسك مثل اللاسو، بحيث يدور الهولا هوب حول يدك.","goodFor":"تحكّم في المستوى الأرضي فوق الرأس.","props":["طوق"]},"hoop-wedgie":{"name":"Wedgie","description":"دوّر الهولا هوب في المستوى الجداري وامسكه في التجويف بين الإبهام والأصابع، ودعه يتدحرج ويتأرجح هناك قبل متابعة الدوران.","goodFor":"تحكّم في القبضة وثبات سلس في الانتقال.","props":["طوق"]},"hoop-knees":{"name":"تدوير الهولا هوب على الركبتين","description":"مع ضمّ القدمين، أبقِ الهولا هوب يدور حول ركبتيك بدفع الركبتين للأمام والخلف.","goodFor":"تمرين الهولا هوب على الجزء السفلي من الجسم والسلم المتحرك.","props":["هولا هوب"]},"hoop-pass":{"name":"تمرير من يد إلى يد","description":"أدر الهولا هوب أمامك ومرّره من يد إلى الأخرى مع كل دورة، مع الحفاظ على ثبات المستوى.","goodFor":"حركات ربط خارج الجسم على الجانبين.","props":["هولا هوب"]},"hoop-isolation":{"name":"عزل الهولا هوب","description":"حرّك يدك حول الهولا هوب بحيث يبقى مركزه ثابتًا في الهواء أمامك بينما يدور الهولا هوب حول تلك النقطة.","goodFor":"خدعة الهولا هوب الكلاسيكية.","props":["هولا هوب"]},"hoop-escalator":{"name":"السلم المتحرك","description":"أبقِ الهولا هوب يدور أثناء تحريكه نزولًا من الخصر إلى الركبتين وصعودًا إلى الصدر، منطقة جسم واحدة كل بار.","goodFor":"يربط كل مناطق الهولا هوب على الجسم في تدفق واحد.","props":["هولا هوب"]},"hoop-neck":{"name":"الهولا هوب على الرقبة","description":"أمِل الرأس قليلًا ودع هولا هوب خفيفًا يدور حول الرقبة، موجّهًا بنبضات صغيرة من الرأس والكتفين.","goodFor":"حركة استعراضية تدرّب النبضات الصغيرة الدقيقة.","avoidIf":["ألم الرقبة."],"props":["هولا هوب"]},"shake-out":{"name":"رجّة الاسترخاء","description":"ضع الأدوات جانبًا ورجّ يديك وساعديك. دع كتفيك يهبطان.","goodFor":"إعادة ضبط قصيرة بين الجولات الصعبة."},"breathe":{"name":"تنفّس وأعد الضبط","description":"قف ثابتًا، أغمض عينيك أو خفّف نظرهما، وخذ أنفاسًا بطيئة من الأنف وأخرجها من الفم.","goodFor":"يخفض معدل ضربات القلب ويصفّي الإحباط بعد السقطات.","breathCue":"شهيق لأربع، زفير لأربع."}}`),t={"warmup-mobility":{name:`إحماء التدفق`,description:`إرخاء الرسغين والكتفين والعمود الفقري والوركين على إيقاع ثابت. استخدمه قبل أي جلسة أدوات.`,focus:`إحماء · مرونة`},"first-throws":{name:`أول الرميات`,description:`كرة واحدة ترسم قوسًا من يد إلى يد على ارتفاع العين، ثم تبادل الكرتين الذي تنمو منه كل الأنماط.`,focus:`شوغリング · أساسيات`},"cascade-builder":{name:`بناء الكاسكيد`,description:`تبادلات الكرتين الواحدة تلو الأخرى حتى تنضم الكرة الثالثة: جولات كاسكيد قصيرة، إعادة ضبط، ثم جولة أخرى.`,focus:`شوغリング · أساسيات`},"juggling-tempo-ladder":{name:`سلّم إيقاع الكاسكيد`,description:`الكاسكيد بثلاثة إيقاعات، أسرع ببضعة نبضات مع كل درجة. ارمِ أخفض في الدرجات السريعة.`,focus:`شوغリング · إيقاع`},"siteswap-sampler":{name:`عيّنة Siteswap`,description:`من الكاسكيد إلى 423 و441 و531، مع الكاسكيد العكسي والشور كمنقّيات للذوق. كل نمط يبدأ وينتهي في الكاسكيد.`,focus:`التحكم بالكرات · الأنماط`},"four-ball-session":{name:`جلسة الأربع كرات`,description:`كرتان في يد واحدة لكل جهة، ثم نافورة الأربع كرات، ثم النافورة المتزامنة.`,focus:`التحكم بالكرات · الأرقام`},"juggling-combo-flow":{name:`تدفق مركّب في التحكم بالكرات`,description:`مجموعة طويلة ومتدفقة: cascade، reverse cascade، Mills mess والـ siteswaps مجمّعة في قطعة موسيقية واحدة.`,focus:`التحكم بالكرات · تركيبات`},"staff-first-spins":{name:`أول دورانات العصا`,description:`دوران العجلة بجانب الجسم، ثم الدوران الأمامي. لفّات بطيئة ومتساوية، واحدة لكل نبضة.`,focus:`العصا · الأساسيات`},"staff-foundations":{name:`أساسيات العصا`,description:`دوران العجلة، الدوران الأمامي، الرقم 8 والتمرير من يد إلى يد مترابطة على النبضة.`,focus:`العصا · الأساسيات`},"staff-flow-weave":{name:`نسيج تدفق العصا`,description:`الرقم 8 إلى الفراشة، دورانات اليد الواحدة والهليكوبتر، متصلة بحيث لا تتوقف العصا أبداً.`,focus:`العصا · التدفق`},"staff-isolation-lab":{name:`مختبر عزل العصا`,description:`العزل وزهرة antispin بإيقاع أبطأ، مع تمريرات خلف الظهر بينهما.`,focus:`العصا · تقني`},"staff-advanced-flow":{name:`تدفق العصا المتقدم`,description:`المفردات الكاملة في قطعة طويلة واحدة: النسج، اللفّات، العزل ودحرجة الرقبة.`,focus:`العصا · التدفق`},"hoop-first-spins":{name:`أول دورانات الهولا هوب`,description:`تدوير الهوب على الخصر مع دفعة أمامية-خلفية، ثم تدوير الهوب حول يد واحدة.`,focus:`الهوب · الأساسيات`},"hoop-body-flow":{name:`تدفق الهوب على الجسم`,description:`تحريك الهوب صعوداً إلى الصدر ونزولاً إلى الركبتين والعودة إلى الخصر، دون توقف.`,focus:`الهوب · على الجسم`},"hoop-off-body":{name:`الهوب خارج الجسم`,description:`دورانات اليد، lasso، wedgies والتمريرات، مع الانتهاء بعزل يثبّت الهوب في الفضاء.`,focus:`الهوب · خارج الجسم`},"hoop-full-flow":{name:`تدفق الهوب الكامل`,description:`على الجسم وخارجه معاً: escalators، تدوير الرقبة وحيل خارج الجسم في تدفق طويل واحد.`,focus:`الهوب · التدفق`},"daily-mixed-flow":{name:`تدفق يومي مختلط`,description:`قليل من كل فن: cascade، دورانات العصا والهوب، مع حركة تنقل بين الأدوات.`,focus:`مختلط · تدريب`}},n=JSON.parse(`{"start-here":{"title":"ابدأ هنا: أسبوعك الأول من التدفق","summary":"اختر أداة واحدة، تدرّب عشر دقائق يومياً على النبضة، ودع شجرة الفتح تخبرك بما يأتي بعد ذلك.","imageAlt":"شكل ثلاثي الأبعاد يقذف كرة تحكم واحدة من يد إلى يد","body":["من الخارج تبدو فنون الفلو مثل السحر: كرات معلقة في الهواء، عصا تتحول إلى ضباب، طوق يدور حول راقص يبدو وكأنه بالكاد يتحرك. من الداخل هي كومة من مهارات صغيرة جدًا، كل واحدة قابلة للتعلم في ظهيرة واحدة، تتراكم حتى تبدو الكومة بلا مجهود. أسبوعك الأول يدور حول قاعدة تلك الكومة.","اختر أداة واحدة للبدء. teaches التجديف التوقيت والتناسق بين اليد والعين؛ teaches staff الطائرات وتغييرات اليد السلسة؛ teaches hoop الإيقاع عبر الجسم كله. يمكنك تعلم الثلاثة، لكن واحدة في كل مرة تبقي انتباهك حيث التقدم. تُظهر شجرة المكافآت كل حركة لكل فن، من أول رمية أو دورة إلى الأنماط المتقدمة، وتفتح التالية عندما تتقن ما بُنيت عليه.","تدرب قليلاً وبشكل متكرر. عشر دقائق مركزة يوميًا أفضل من ساعة يوم الأحد، لأن التناسق يترسخ بين الجلسات، خاصة أثناء النوم. روتين قصير من صفحة الروتينات، تسخين، وبعض الخطوات المعدودة من حركتك الحالية هو ممارسة كاملة.","تدرب على الإيقاع من اليوم الأول. كل حركة في SynthFlow تُعد في بارات على tempo، مع موسيقى أو إيقاع مُولَّد يطابقها. الإيقاع يمنحك شيئًا تتعلق به عندما لا تتعاون الأداة، ويجعل التقدم قابلًا للقياس: جولة نظيفة عند 90 BPM هذا الأسبوع، 100 الأسبوع القادم.","توقع السقوط. الجميع يسقط، بما في ذلك المحترفون في التدريب. السقوط يخبرك أي رمية أو التقاط يحتاج انتباهًا؛ لا يقول شيئًا عن الموهبة. ارفع الأداة، انتظر الضربة القوية التالية، وأعد المحاولة. بنهاية الأسبوع سيكون لديك حركة تستطيع أداءها دون تفكير، وتلك هي اللحظة التي يبدأ فيها الفلو."]},"counting-and-the-beat":{"title":"العدّات والبارات والإيقاع","summary":"لماذا تُعد كل حركة في بارات على tempo، وكيف تربط رمياتك ودوراتك بالموسيقى.","imageAlt":"شكل ثلاثي الأبعاد يتقن التجديف بثلاث كرات cascade مع أقواس مرسومة فوق اليدين","body":["الموسيقى مصنوعة من ضربات مجمعة في بارات، عادة أربع ضربات في البار. حركات الفلو مصنوعة من دورات: رمية من كل يد، نصف دورة للعصا، مدار واحد للطوق. عندما تهبط دورة على الضربة، تصبح الحركة والموسيقى شيئًا واحدًا. لهذا يقيس SynthFlow كل خطوة روتين في بارات بدلاً من ثوانٍ، ولهذا تخبر كل حركة كم ضربة تستغرق دورة واحدة.","في cascade بثلاث كرات تهبط كل رمية على ضربة، بالتناوب يمينًا ويسارًا. في دورة العصا الأمامية عادة يستغرق نصف دورة ضربة واحدة. تدوير الطوق عند الخصر عادة مدار واحد لكل ضربة على tempo مريح. تسمي العدّات في المشغل ما يحدث في كل ضربة، ويتحرك الشكل ثلاثي الأبعاد بالضبط على نفس ساعة الصوت، حتى تتمكن من تقليده في الوقت المناسب.","يُقاس Tempo بالضربات في الدقيقة (BPM). لكل حركة نطاق مريح: بطيء بما يكفي للبقاء نظيفًا، سريع بما يكفي لتحافظ الأداة على زخمها. تحت النطاق تتوقف الأدوات الدوارة وتذهب الرميات عاليًا جدًا فتنحرف؛ فوقه تبدأ في التسرع والسقوط. يحذرك المنشئ عندما تكون خطوة خارج نطاق حركتها.","ابدأ كل خطوة على الضربة القوية، \\"واحد\\" البار. يمنحك العد التمهيدي بارًا لتحريك الأداة قبل أن تبدأ البارات المعدودة. إذا فقدت الإيقاع، لا تطارده: توقف، استمع لـ\\"واحد\\" التالية، وعد. يسمي الموسيقيون هذا إيجاد قمة البار، وهو يعمل لفناني الفلو أيضًا.","العد بصوت عالٍ لبضع جلسات يساعد أكثر مما يبدو. قول \\"واحد، اثنان، ثلاثة، أربعة\\" أثناء التجديف يربط الإيقاع بنفسك وصوتك، فيبقى عندما يصعب النمط. بمجرد أن تعيش العدّات في جسدك، أوقف العدّ المنطوق في الإعدادات ودع الموسيقى تحملك."]},"tempo-ladders":{"title":"سلالم Tempo: البطيء سلس، والسلس سريع","summary":"اصعد بضع BPM في كل مرة من tempo يمكنك أداؤه بنظافة، وانزل فورًا في اللحظة التي ينكسر فيها الشكل.","imageAlt":"شكل ثلاثي الأبعاد يدير عصا أمام الجسم في wall plane","body":["سلم Tempo هو نفس الحركة مكررة على tempos متزايدة: ثمانية بارات عند 80 BPM، ثمانية عند 88، ثمانية عند 96، وهكذا. إنها الطريقة الأكثر موثوقية لجعل الحركة أسرع دون جعلها أكثر فوضى، والعديد من الروتينات المدمجة مبنية حولها.","ابدأ على درجة يمكنك أداؤها بنظافة، حتى لو بدت سهلة جدًا. الهدف من الدرجة السفلية ليس التحدي؛ بل تدريب الشكل الصحيح حتى يكون الشكل هو ما يتسارع. اصعد بمقدار صغير، حوالي خمسة إلى عشرة بالمائة. القفزات الكبيرة تغير الحركة: تصبح الرميات أقل، والدورات أكثر ضحالة، وتنتهي بتدريب خدعة مختلفة.","توقف عن الصعود عندما ينكسر الشكل، وليس عندما تسقط. راقب العلامات المبكرة: القمم تصبح غير متساوية، العصا تنحرف عن طائرتها، الطوق يرتفع أو ينخفض. تلك هي الإشارات للعودة درجة للأسفل وتشغيلها مرة أخرى. إنهاء سلم بجولة نظيفة على tempo أقل بقليل من حدك يعلم جسدك ذلك Tempo؛ وإنهاؤه بانهيار يعلم الانهيار.","Tempos البطيئة أصعب مما تبدو للأدوات الدوارة، لأن الأداة لديها زخم أقل لحملها خلالها. إذا توقفت عصا أو طوق في أسفل نطاقها، احتفظ بـ tempo وكبّر الحركة قليلاً، أو خذها بنصف الوقت مع الموسيقى: دورة واحدة كل ضربتين.","تتبع أعلى tempo نظيف لكل حركة في Progress. رؤية ذلك الرقم يزحف صعودًا عبر الأسابيع دافع جيد، ويُظهر أيضًا عندما تستقر حركة وتحتاج تدريبًا مختلفًا بدلاً من المزيد من نفس الشيء."]},"siteswap-notation":{"title":"Siteswap: التجديف مكتوبًا كأرقام","summary":"كل رقم هو عدد الضربات لاحقًا التي تُرمى فيها الكرة مرة أخرى؛ الأرقام الفردية تعبر، والزوجية تبقى، والمتوسط هو عدد الكرات.","imageAlt":"شكل ثلاثي الأبعاد يتقن التجديف بـ siteswap 441 مع رميتين عاليتين وzip سريع","body":["أنماط التجديف صعبة الوصف بالكلمات وسهلة الوصف بالأرقام. Siteswap، الذي طُوّر بشكل مستقل في منتصف الثمانينيات من قبل مجدفين في كامبريدج، وكالتك، وسانتا كروز، يكتب النمط كتسلسل متكرر من الأرقام. هكذا يشارك المجدفون الأنماط، ويتحققون مما إذا كانت فكرة ما يمكن أن تعمل، ويكتشفون خدعًا لم يجربها أحد. يستخدمه SynthFlow لتحريك كل نمط تجديف من نفس المحرك.","تخيل اليدين ترميان بالتناوب في كل ضربة: يمين، يسار، يمين، يسار. كل رقم في siteswap يقول كم ضربة من الآن ستُرمى الكرة التي رُميت في هذه الضربة مرة أخرى. 3 يعود بعد ثلاث ضربات؛ لأن ثلاثة فردي، يهبط في اليد الأخرى. cascade بثلاث كرات هو مجرد 3، 3، 3، 3 إلى الأبد، مكتوب ببساطة كـ 3. 4 يعود بعد أربع ضربات في نفس اليد، وهو fountain بأربع كرات.","الأرقام الصغيرة لها معانٍ خاصة. 2 يعود إلى نفس اليد بعد ضربتين، وهو عمليًا يعني حمل الكرة للحظة. 1 يعبر إلى اليد الأخرى في الضربة التالية مباشرة، zip سريع عبر المسار. 0 هو يد فارغة. الأرقام الأكبر رميات أعلى: 5 هي رمية عابرة عالية.","اقرأ النمط رقمًا برقم. في 441، رميتان تبقىان على جانبهما بينما تعبر كرة ثالثة تحتهما. في 531، رمية عابرة عالية تصعد بينما رمية cascade وzip تحافظان على تحرك الكرتين الأخريين. في 423، رمية بارتفاع fountain، وكرة محمولة، ورمية cascade تتناوب.","تخبرك نظرية المتوسط كم كرة يحتاج النمط: اجمع الأرقام واقسم على عددها. 441 مجموعه 9 على ثلاثة أرقام، إذن ثلاث كرات. إذا لم يكن المتوسط عددًا صحيحًا، لا يمكن تجديف التسلسل. فحص ثانٍ هو أنه لا يمكن أن تهبط كرتان في نفس اليد في نفس الضربة، وهكذا يكتشف المجدفون الأنماط المستحيلة قبل تجربتها.","لـ siteswap أيضًا تدوين لرمي كلتا اليدين معًا، مكتوب بين قوسين مثل (4,4)، ولرمي كرتين من يد واحدة في وقت واحد، مكتوب بين قوسين مربعين. لا تحتاج أيًا من هذا لتجدف جيدًا، لكن بمجرد أن تنقر الأرقام، يبدأ كل اسم نمط جديد في شرح نفسه. افتح قاموس Flow للأرقام الفردية."]},"planes-and-geometry":{"title":"الطائرات: wall وwheel وfloor","summary":"الأدوات الدوارة تعيش في طائرات مسطحة؛ الحفاظ على الطائرة نظيفة هو معظم ما يجعل العصا أو الطوق يبدو حادًا.","imageAlt":"شكل ثلاثي الأبعاد ينسج عصا في شكل 8 على جانبي الجسم","body":["عصا أو طوق دوّار يكتسح سطحًا مسطحًا، يسمى طائرته. يصف فناني الفلو ثلاث طائرات أساسية بالنسبة للجسم. wall plane أمامك، مثل لوح زجاج يمكنك ضغط راحتي يديك عليه. wheel plane بجانبك، بالطريقة التي تدور بها عجلة عربة على جانبك. floor plane أفقية، موازية للأرض، كما في helicopter فوق الرأس أو lasso.","الطائرات النظيفة هي ما يقرأه الجمهور كمهارة. عصا تتمايل خارج طائرتها تبدو غير واثقة حتى لو لم تسقط أبدًا؛ طوق يبقى مسطحًا تمامًا أثناء pass يبدو بلا مجهود. معظم التدريب المبكر يدور بهدوء حول الطائرات: منع المعصمين من الالتواء، منع المرفقين من الاتساع، والسماح للكتفين بتحريك الأداة بدلاً من اليدين.","العديد من الخدع تُعرَّف بتغيير الطائرات. figure-8 weave ينقل العصا من wheel plane على جانب إلى wheel plane على الجانب الآخر. butterfly يطويها خلف الكتف ويعيدها. escalator يمشي بطوق صعودًا وهبوطًا على الجسم بينما تبقى طائرته مستوية. تعلم أين تبدأ وتنتهي كل حركة في الفضاء هو كيف تربطها في الفلو.","يمكن للعارض ثلاثي الأبعاد رسم الطائرة أثناء تدريبك. شغّله عند تعلم دورة جديدة وقارن: هل تميل عصاك نحوك في الأعلى؟ هل ينخفض الطوق في الأمام؟ مرآة أو كاميرا هاتف تُظهر نفس الشيء. المشاهدة من العرض الجانبي مفيدة بشكل خاص لحركات wall-plane، لأن الميل غير مرئي من الأمام.","تساعد الطائرات أيضًا في السلامة والمساحة. قبل الجلسة، تحقق من أن كل طائرة ستستخدمها خالية: الجدار أمامك، الجدران بجانبك، والسقف فوقك لحركات floor-plane وفوق الرأس. طائرة نظيفة لا شيء فيها هي طائرة واثقة."]},"spin-and-antispin":{"title":"Spin وantispin وisolations","summary":"كيف تدور الأداة مقارنة باليد يمنح ثلاث عائلات من الحركة: spin وantispin وisolation.","imageAlt":"شكل ثلاثي الأبعاد يرسم زهرة أنتيسبين رباعية البتلات بعصا","body":["عندما تحرك أداة دوارة في دائرة، يحدث دورانان في آن واحد: يدك تسير في دائرة، والأداة تدور حول مركزها. نظرية الفلو تسمي الحركات بناءً على علاقة هذين الدورانين. إنها نفس المفردات للعصا والهولا والبويا، ولهذا تنتقل المهارات بين الأدوات بسهولة.","في السبين، ويسمى أحيانًا إنسپين، تدور الأداة في نفس اتجاه دائرة اليد. هذا هو الاتجاه الطبيعي؛ معظم الدورات الأولى تكون إنسپين دون أن يسميها أحد كذلك. الشكل المرسوم زهرة تتجه بتلاتها للخارج.","في الأنتیسبین تدور الأداة عكس اتجاه دائرة اليد. يبدو غريبًا في البداية، كأنك تربت على رأسك وتدلك بطنك، لكنه يرسم زهرة البتلات الكلاسيكية. عدد البتلات يعتمد على عدد دورات الأداة لكل دورة يد: ثلاث دورات عكسية لكل دورة يعطي أربع بتلات، وهي الأنتیسبین رباعي البتلات في شجرة العصا.","الإيزوليشن هو الحالة الخاصة حيث تدور اليد بحيث تبدو نقطة واحدة من الأداة متجمدة في الفضاء. مع العصا يبقى المركز ثابتًا بينما تكتسح الأطراف حوله؛ مع الهولا يبقى مركز الحلقة أو نقطة على الحافة ثابتة. تبدو الإيزوليشنات وكأن الأداة تطفو والجسم يدور حولها. تتطلب مسارات يد دقيقة، مما يجعلها تدريبًا ممتازًا لكل حركة أخرى.","تعلم هذه ببطء وعلى الإيقاع. الأنتیسبین خاصة يستفيد من وتيرة أقل بكثير من سرعة دورانك المعتادة، مع عدّات تسمي مكان الأداة: أعلى، جانب، أسفل، جانب. استخدم الشبح في العارض ثلاثي الأبعاد لرؤية موضع الإيقاعة التالية، والأثر لترى إن كانت زهرتك متساوية البتلات.","بمجرد أن تصبح السبين والأنتیسبین والإيزوليشن مألوفة في مستوى واحد، جربها في مستوى آخر. تبقى النظرية كما هي ويتعلم جسمك أن المستوى مجرد إعداد، وهذه خطوة كبيرة نحو الارتجال في الفلو."]},"sequencing":{"title":"كيف تُبنى روتينات الفلو","summary":"سخّن، تدرب على تركيز واحد مع روابط تتدفق، اجعل قفزات الإيقاع صغيرة، واختم بتهدئة سهلة.","imageAlt":"شكل ثلاثي الأبعاد يمرر هولا من يد إلى يد أمام الجسم","body":["روتين الفلو الجيد له نفس شكل المجموعة الموسيقية الجيدة: افتتاحية تدفئ المكان، وسط يبني، ونهاية تتيح للجميع التنفس. روتينات SynthFlow المدمجة تتبع هذا الشكل، ومساعد البنّاء يتحقق من روتينك مقارنة به.","ابدأ بالإحماء. دوائر الرسغ ودوائر الذراع وتدوير الكتف تأخذ المفاصل التي ستحمّلها عبر مداها بوتيرة لطيفة. دقيقتان أو ثلاث تكفي لجلسة قصيرة؛ الجلسات الأطول والأيام الباردة تستحق أكثر.","أعطِ كتلة التدريب تركيزًا واحدًا. اختر حركة تعمل عليها وأحطها بحركات تتصل بها. يُظهر البنّاء كيف تتصل كل خطوة بالسابقة: التدفق مباشرة من نفس وضع اليد، إعادة قبضة صغيرة، وضع الأداة أرضًا، أو البناء على حركة سابقة. الروتينات المتدفقة تبدو كالرقص؛ الروتينات المليئة بالإنزالات تبدو كقائمة.","اجعل تغييرات الإيقاع صغيرة بين الخطوات. القفز من 80 إلى 130 BPM يعيد ضبط توقيتك ويدعو للسقوط. يرصد المساعد القفزات التي تزيد عن الربع تقريبًا، ويطوي النصف والضعف بحيث يمكن لخطوة هولا بـ 70 BPM أن تجاور مقطعًا بـ 140 BPM.","عد إلى حركة التركيز أكثر من مرة. التكرار خلال الجلسة، مع حركات أخرى بينها، يبني المهارة أفضل من كتلة طويلة واحدة، لأن كل عودة محاولة جديدة من نقطة بداية مختلفة قليلًا.","اختم بتهدئة: حركة سهلة بوتيرة بطيئة، أو راحة قصيرة مع بضع أنفاس. تخفض معدل ضربات القلب وتمنح تنسيقك نهاية هادئة يتذكرها. عاين الروتين قبل تشغيله وأزل أي شيء هو بوضوح طموح الأمس."]},"effort":{"title":"متى ترفع الإيقاع","summary":"ارفع عندما تصمد الفورمة وتكون منتعشًا؛ خفف عندما تتذبذب القمم أو تشتد القبضة أو تبدأ السقطات بالتجمع.","imageAlt":"شكل ثلاثي الأبعاد يشعو خمس كرات في كاسكيد عالٍ","body":["التقدم في الفلو يأتي من التدريب على حافة قدرتك، لكن الحافة تتحرك. بعض الأيام تكون أبعد مما تتوقع؛ وبعض الأيام تتراجع. تعلم قراءتها مهارة تساوي أي حركة.","ارفع عندما تصمد الأساسيات. إذا كانت قممك متساوية، وعصاك تبقى في مستواها، وهولاك يبقى أفقيًا، وتنفسك سهل، خذ الدرجة التالية من سلم الإيقاع أو جرب التمرين التالي في التدرج. أول خمس عشرة دقيقة من الجلسة، بعد الإحماء، عادة أفضل وقت للمواد الجديدة.","خفف عندما تتدهور الجودة. السقطات المتجمعة، القبضة المشدودة، الأكتاف الزاحفة نحو أذنيك، والتنفس المحبوس كلها تقول إن جهازك العصبي متعب. اخفض الإيقاع، عد إلى حركة تتقنها، أو أنهِ الجلسة. الدفع عبر التعب غالبًا يتدرب على الأخطاء.","راقب التحذيرات الجسدية أيضًا. الرمي والدوران المتكرر يحمّلان الرسغين والساعدين والكتفين. الألم الذي يتلاشى خلال يوم طبيعي. الألم الحاد، أو الألم الذي يزداد أثناء التدريب، أو التنميل أو الوخز أسباب للتوقف والراحة؛ الأعراض المستمرة تستحق طبيبًا.","استخدم تقييم الجهد بعد كل جلسة. يقرأه معالج التدريب: عدة جلسات صعبة متتالية فيقترح شيئًا ألطف، وعدة سهلة فيقترح المزيد قليلًا. التقييمات الصادقة تصنع اقتراحات أفضل."]},"drops-are-data":{"title":"السقطات بيانات","summary":"السقطة تخبرك أي رمية أو التقاطة تصلح؛ اعتبارها فشلًا يعلمك فقط أن تتوتر.","imageAlt":"شكل ثلاثي الأبعاد يتبادل كرتي شعوذة بين اليدين","body":["كل لاعب شعوذة لديه أرضية مغطاة بالكرات في مرحلة ما. كل لاعب عصا سمع صوت الارتطام. الفرق بين من يستمر في التحسن ومن يستسلم نادرًا ما يكون الموهبة؛ بل طريقة تعاملهم مع السقطة.","السقطة قياس. تخبرك أي رمية أخطأت، وأي التقاطة مددت يدك إليها، وأي لحظة من الدوران فقدت مستواها. إذا استمرت نفس الكرة في السقوط أمامك، فرمياتك تنزلق للأمام. إذا جاءت السقطات بعد ست رميات، فشيء في رميتك الثالثة أو الرابعة خطأ. راقب أين ومتى، ثم اختر شيئًا واحدًا تغيره.","اعتبار السقطات فشلًا له ثمن. الخوف يشد الكتفين ويقصر النفس، والتوتر يجعل الحركات أصغر وأسرع، مما يسبب المزيد من السقطات. الاستجابة الهادئة — التقط، تنفس، انتظر الضربة القوية، أعد — ليست ممتعة فقط؛ بل هي الاستجابة الصحيحة تقنيًا.","احسب الجولات النظيفة، لا السقطات. يتقن SynthFlow حركة عندما تجمع جولات نظيفة كافية ودقائق تدريب، فالسقطات على الطريق مجرد جزء من الدقائق. بعض الأيام ستسجل عشر جولات نظيفة، وبعضها اثنتين. كلا اليومين يُحسب.","أسقط عن قصد أحيانًا. عند تعلم حركة جديدة، تدرب على الرمية الأولى أو نصف الدورة الأولى ودعها تسقط. ثم أضف الالتقاط. عزل اللحظة الخطرة يصغّرها، وتتعلم أن الأرضية ليست عدوك. إنها فقط حيث تذهب الأداة عندما تتعلم."]},"safety":{"title":"السلامة: المساحة والأدوات والعلامات الحمراء","summary":"أفرغ مستوياتك، اختر أدوات متسامحة، سخّن، وتوقف عند الألم الحاد أو التنميل أو الدوخة.","imageAlt":"شكل ثلاثي الأبعاد يدور بعصا أفقيًا فوق الرأس مع مساحة خالية حوله","body":["فنون الفلو منخفضة المخاطر مقارنة بمعظم الرياضات، لكن الأدوات تتحرك بسرعة وتسافر أبعد مما تتوقع. بعض العادات تحافظ على سلامة تدريبك، ولمن حولك، وللأثاث.","أفرغ مساحتك قبل البدء. تحقق من كل مستوى ستستخدمه: أمامك، على الجانبين، وفوقك. العصا والهولا يحتاجان مساحة أكبر مما تظن، عادة دائرة لا تقل عن مدى ذراعيك زائد طول الأداة في كل اتجاه، مع لا شيء قابل للكسر في المتناول. في الداخل، راقب إضاءة السقف والمراوح؛ في الخارج، راقب الأرض غير المستوية والمارة.","استخدم أدوات متسامحة أثناء التعلم. كرات الشعوذة المحشوة لا تتدحرج بعيدًا. العصي المبطنة أو ذات الأطراف الإسفنجية تؤلم أقل عندما تصيب رأسك، وهذا سيحدث. الهولا الأكبر والأثقل يدور أبطأ ويسهل إبقاؤه. ارتقِ إلى أدوات أسرع أو أكثر لمعانًا عندما تصبح الأساسيات تلقائية.","سخّن قبل كل جلسة وابنِ الحجم تدريجيًا. الرمي والدوران متكرران، والحمل المتكرر على أنسجة باردة هو السبب المعتاد لآلام الرسغين والمرفقين. إذا أضفت الكثير من التدريب فجأة، أضف أيام راحة أيضًا.","توقف عند العلامات الحمراء: ألم حاد أو كهربائي، تنميل أو وخز في اليدين، ألم يزداد مع الاستمرار، دوخة، أو إصابة في الرأس مع أي أعراض مستمرة. حركات الرقبة ولفات التلامس تستحق عناية إضافية؛ تعلمها ببطء مع أداة مبطنة.","هذا التطبيق يعلّم التقنية، وليس الرعاية الطبية. الحمل، الإصابات الحديثة، مشاكل المفاصل، وأي شيء يقلقك هي أسباب لاستشارة مختص مؤهل قبل إضافة حمل جديد. الأداء بالنار تخصص منفصل له تدريب سلامة خاص به؛ SynthFlow لا يعلّمه."]},"warm-up":{"title":"لماذا الإحماء مهم لعمل الأدوات","summary":"من دقيقتين إلى خمس دقائق من تحريك الرسغين والذراعين والكتفين والوركين تجعل الدورانات أكثر سلاسة وتحمي مفاصلك.","imageAlt":"شكل ثلاثي الأبعاد يقوم بدوائر بطيئة بالرسغين مع تمديد الذراعين للأمام","body":["ممارسة الـ flow تبدو لطيفة، لكنها تطلب الكثير من مفاصل قليلة. التجديف يكرر نفس الرمية آلاف المرات؛ تدوير العصا يمرّر الرسغين عبر مداهما الكامل؛ والهولا هوب يحرّك العمود الفقري والوركين في كل دورة. الأنسجة الدافئة تتحمل هذا التكرار أفضل بكثير من الباردة.","الإحماء الجيد للـ flow قصير ومحدد. دوائر الرسغين في الاتجاهين تهيّئ المفاصل التي تقوم بمعظم العمل. دوائر الذراعين وتدوير الكتفين توقظ الكفة المدورة ولوحي الكتف، اللذين يتحكمان في مستوى كل دوران. دوائر الوركين ولف الجذع الأهم للهولا هوب. أنصاف دوائر الرقبة، وليس اللف الكامل أبداً، تخفف التوتر الناتج عن النظر لأعلى نحو النمط.","تحرك ببطء وعلى الإيقاع. خطوات الإحماء في SynthFlow تُعد مثل كل شيء آخر، بإيقاع مريح، فتصبح الدقائق الأولى من الجلسة ضبطاً لتوقيتك أيضاً. بحلول وقت إخراج الأدوات، تكون تتحرك مع الموسيقى بالفعل.","أنهِ الإحماء بالأداة بنصف السرعة. بضع رميات بطيئة، أو دوران أمامي خفيف، أو دورة هولا كبيرة وبطيئة تربط عمل الحركة بالحركة التي أنت على وشك التدرب عليها، وتخبرك كيف يشعر جسمك اليوم.","الإحماء أيضاً انتقال ذهني. نفس الثلاث دقائق في بداية كل جلسة تصبح إشارة على أن التدريب قد بدأ. في الأيام المزدحمة، يكون الإحماء أحياناً هو التدريب كله، وهذا يُحتسب أيضاً."]},"anatomy-basics":{"title":"الجسم خلف الأدوات","summary":"الساعدان يقبضان ويطلقان، الكتفان يوجّهان المستوى، الجذع يبقيك ثابتاً: خريطة بلغة بسيطة للـ flow.","imageAlt":"شكل ثلاثي الأبعاد يلعب بالهولا عند الخصر مع الجزء العلوي المرتخي","body":["لا تحتاج معرفة التشريح لتتجديف، لكن خريطة بسيطة تساعدك على فهم ما يتعب، وما يجب إحماؤه، وما يجب إراحته. قسم العضلات في Learn فيه نموذج تفاعلي؛ هذه المقالة هي الجولة القصيرة.","الساعدان يقومان بمعظم العمل الدقيق. العضلات على جانب الراحة تغلق الأصابع وتثني الرسغ؛ العضلات على ظهر الساعد تفتح الأصابع وتمد الرسغ. الإمساك والإطلاق، والقبض على العصا وتركها تتدحرج، كل هذا يحدث هنا. إجهاد الساعد هو الإحساس الأكثر شيوعاً بعد جلسة طويلة، ولهذا القبضة المرتخية توجيه متكرر.","الكتفان يوجّهان. العضلات الدالية ترفع الذراعين؛ الكفة المدورة، أربع عضلات صغيرة حول المفصل، تبقي العضد في مركزه أثناء الحركة. العضلات حول لوحي الكتف تثبّت المنظومة كلها. عندما تنحرف العصا عن مستواها، السبب غالباً الكتف وليس اليد.","الجذع يبقيك هادئاً. في التجديف، الجذع الثابت يمنع النمط من التشتت. في الهولا هوب، عضلات البطن والظهر تدفع الهولا بنبضات صغيرة للأمام والخلف. الوركان والساقان هما قاعدتك: الرُكب اللينة تمتص الحركة وتتيح لك نقل الوزن دون إزعاج الأداة.","عيناك وأذنك الداخلية مهمتان أيضاً. التجديف يدرّبك على مراقبة القمم، وليس اليدين؛ التدوير يدرّب توازنك. الجلسات القصيرة مع فترات راحة تتيح لكليهما التكيف دون دوخة. اعتبر هذه الخريطة معرفة عامة، وليست تشخيصاً، وراجع مختصاً لأي ألم لا يهدأ."]},"biomechanics-safety":{"title":"الرسغان والكتفان والحمل المتكرر","summary":"قبضة مرتخية، رسغان محايدان، وحجم تدريجي يبقون المفاصل التي تقوم بكل العمل سعيدة.","imageAlt":"شكل ثلاثي الأبعاد يدوّر عصا بيد واحدة فوق ظهر اليد","body":["إصابات الـ flow نادراً ما تكون دراماتيكية. هي دائماً تقريباً إفراط في الاستخدام: تكرار كثير جداً، قبض كثير جداً، راحة قليلة جداً. الخبر الجيد أن نفس العادات القليلة تمنع معظمها.","أرخِ القبضة. كرة التجديف تحتاج فقط ضغطاً كافياً لتبقى في اليد؛ العصا تحتاج حلقة أصابع مرتخية تتدحرج داخلها. الضغط المتوتر يتعب عضلات الساعد ويحمّل الأوتار عند المرفق. إذا ابيضّت مفاصلك أو حرقت ساعداك بعد دقائق، ارتخِ واخفض الإيقاع.","أبقِ الرسغين قريبين من الوضع المحايد عندما تستطيع. التدوير يأخذ الرسغين عبر مدى واسع، وهذا لا بأس به باعتدال. إبقاؤهما في نهاية مداهما لفترات طويلة، أو إجبار رسغ متيبس على الدوران، هو ما يهيّجهما. دع المرفق والكتف يشاركان الحركة.","دع الكتفين يعملان، لكن دون تقويس. الدوائر الكبيرة تأتي من مفصل الكتف؛ الكتف المرفوع يضغط ويتعب بسرعة. تحقق في المرآة أو وضع الكاميرا أن كتفيك يبقيان منخفضين، خاصة في الحركات العلوية مثل الهليكوبتر واللاسو.","ابنِ الحجم تدريجياً. إذا كنت تتتدرب عادة عشرين دقيقة، لا تقفز إلى ساعتين لأن مهرجاناً قادم. زد الوقت الإجمالي بمقدار متواضع كل أسبوع واحتفظ بيوم سهل على الأقل. بدّل الأدوات لتوزيع الحمل: عمل الهولا يريح الساعدين اللذين يتعبهما التجديف.","الألم الذي يتلاشى خلال يوم هو تكيف طبيعي؛ الألم الذي يستمر أو يزداد أو يأتي مع تنميل ليس كذلك. ارتح، قلل الحجم، واطلب مشورة مختص إذا استمر. هذا تعليم، وليس نصيحة طبية."]},"choosing-props":{"title":"اختيار أدواتك الأولى","summary":"أكياس الفاصولياء للتجديف، عصا خفيفة مبطنة، وهولا كبير للبالغين تجعل الأسابيع الأولى أسهل بكثير.","imageAlt":"شكل ثلاثي الأبعاد يدوّر هولا حول يد واحدة","body":["الأدوات الجيدة للمبتدئين تجعل التعلم أسرع وأقل إحباطاً. لا تحتاج معدات غالية، لكن بعض الخيارات مهمة.","للتجديف، ابدأ بثلاث كرات أكياس فاصولياء بوزن حوالي 60 إلى 130 غراماً لكل واحدة. أكياس الفاصولياء لا ترتد أو تتدحرج بعيداً عند السقوط، مما يوفر الكثير من الجري خلفها. يجب أن تتسع بشكل مريح في راحة يدك. كرات المسرح، وهي أكبر، والكرات السيليكونية المرتدة للمرحلة اللاحقة. الألوان المتطابقة تساعدك على رؤية النمط؛ ثلاثة ألوان مختلفة تساعدك على تتبع الكرات الفردية عند تعلم siteswaps.","للعصا، عصا التدوير للمبتدئين عادة ما تكون حوالي 1.2 إلى 1.5 متر، خفيفة، بأطراف مبطنة أو مطاطية. كدليل تقريبي يجب أن تصل بين صدرك وكتفك عند وقوفها عمودياً. العصا الأطول والأثقل تدور أبطأ وأكثر سلاسة بعد إتقان الأساسيات، لكنها أصعب في البداية وتؤلم أكثر عند الاصطدام. قبضة في المنتصف تساعد.","للهولا، ابدأ أكبر وأثقل مما تظن. هولا المبتدئين للبالغين عادة ما يصل بين الخصر والصدر عند وقوفه على الأرض. الهولا الأكبر يدور أبطأ، مما يمنحك وقتاً لإيجاد الإيقاع للهولا عند الخصر. الهولا الأصغر والأخف يناسب الحركات السريعة بعيداً عن الجسم بعد أن تصبح مرتاحاً.","أياً كان ما تختاره، تأكد أن نطاق إيقاع الحركة يناسب الأداة. الأدوات الأثقل عادة تحب الإيقاعات المنخفضة. إذا كان النطاق المريح في التطبيق يبدو متسرعاً مع أداتك، اضبط إيقاعك الخاص في المنشئ؛ العد يتبع."]},"practice-at-home":{"title":"التدريب في المنزل وفي الحديقة","summary":"جلسات يومية قصيرة، مساحة واضحة، حافة سرير أو أريكة لالتقاط السقطات، وجلسة في الحديقة عندما تستطيع.","imageAlt":"شكل ثلاثي الأبعاد يهز الذراعين بين جولات التدريب","body":["معظم فناني الـ flow يتعلمون في المنزل، بضع دقائق في كل مرة. القليل من التجهيز يجعل التدريب المنزلي أسهل في البدء وأسهل في الاستمرار.","اعثر على مكانك. للتجديف، الوقوف أمام سرير أو أريكة يعني أن الكرات الساقطة تهبط عند ارتفاع الخصر بدلاً من التدحرج تحت الأثاث، ويمنعك أيضاً من المشي للأمام. للعصا والهولا، اعثر على أكبر مساحة واضحة لديك، تحقق من السقف، وأبعد أي شيء قابل للكسر. الحديقة أو المنتزه أفضل للدورانات الكبيرة.","أبقِ الأدوات مرئية. الكرات على المكتب تُلعب بها أثناء المكالمات واستراحات الشاي؛ الهولا بجانب الباب يُستخدم. كلما قل الجهد للبدء، زاد تكرارك. روتين خمس دقائق يُحتسب، وعدة جلسات قصيرة في اليوم تتراكم بسرعة.","استخدم التطبيق كإطار. اختر روتينًا أو دع المعالج يقترح واحدًا، شغّله كاملًا، وسجّل مجهودك. البرامج القصيرة مثل Zero to Cascade تمنح كل أسبوع هدفًا واضحًا، مما يمنعك من التشتت بين الحركات.","تدرّب مع الآخرين عندما تستطيع. أندية الجgling ومدارس السيرك وتجمعات الـ flow في الحدائق موجودة في مدن كثيرة. مشاهدة شخص متقدم عنك بخطوة غالبًا ما تصلح شيئًا لم يستطع شرح فيديو إصلاحه، وتعليم شخص متأخر عنك بخطوة يجعل تقنيتك أنت أوضح. أحضر أدواتك، واسأل الناس عمّا يعملون عليه، وشارك ما علّمتك إياه العدّات."]},"learning-with-the-app":{"title":"التعلّم مع المدرب ثلاثي الأبعاد","summary":"أبطئه، اعكسه، شغّل الشبح والمسارات، غيّر الكاميرا، واستخدم وضع الكاميرا للحصول على ملاحظات.","imageAlt":"مجسّم ثلاثي الأبعاد يؤدي عزل staff مع مسار يُظهر المسار","body":["كل حركة في SynthFlow مُتحرّكة ثلاثية الأبعاد من نفس ساعة الموسيقى، لذا يكون المجسّم دائمًا على الإيقاع تمامًا. عند استخدامه جيدًا، يكون العارض معلمًا صبورًا لا يتعب أبدًا من إظهار نفس الرمية لك.","أبطئه أولًا. سلّم التدرّج في كل حركة يبدأ بنسخ بطيئة وجزئية، ثم باليدين فقط، ثم الحركة الكاملة على الإيقاع. نصف السرعة يحافظ على علاقات التوقيت سليمة بينما يمنح عينيك وقتًا للمتابعة.","اعكس المجسّم إذا كنت تتعلم أفضل وأنت مواجه لمعلم، وغيّر الكاميرا عندما يخفي منظور ما شيئًا. المناظر الجانبية تُظهر ميل الـ staff وانحراف الرمية؛ المناظر العلوية تُظهر مستويات الـ hoop ومسارات الهليكوبتر. المسارات ترسم أين كان كل أداة، مما يحوّل الضباب إلى شكل يمكنك دراسته. الشبح يُظهر أين ستكون الأداة في الإيقاع التالي.","راقب الأخطاء الشائعة. كل حركة يمكنها إظهار عيوبها النموذجية، مثل الانحراف للأمام أو الارتفاعات غير المتساوية أو الاستعجال، تُعرض عمدًا بشكل خاطئ على المجسّم، مع الإشارة التي تصلحها. التعرّف على العيب في النموذج يجعل الإحساس به في جسدك أسهل بكثير.","وضع الكاميرا يمنحك ملاحظات عنك. بإذنك، يتتبع يديك وجسدك أثناء التدريب ويقارن توقيتك بالإيقاع. المعالجة تحدث على جهازك. ليس مثاليًا، والإضاءة الجيدة تساعد، لكن حتى الملاحظات التقريبية حول ما إذا كنت مبكرًا أو متأخرًا قيّمة.","أخيرًا، أغلق العارض أحيانًا. تدرّب مع الموسيقى فقط وثق بالعدّات. الهدف هو حركة تستطيع أداءها دون مشاهدة أي شيء على الإطلاق."]},"music-for-flow":{"title":"إيجاد موسيقى مناسبة","summary":"الإيقاعات المقيسة، ونصف وضِعف الوقت، والإيقاع المُولَّد، ومقاطعك الخاصة، كلها تحافظ على دقة العدّات.","imageAlt":"مجسّم ثلاثي الأبعاد يلعب بالـ hoop عند الصدر مع رفع الذراعين","body":["الموسيقى تحوّل التدريب إلى flow، لكن فقط إذا كان الإيقاع في الموسيقى هو الإيقاع في العدّات. مقطع بـ 118 BPM تحت روتين بـ 120 BPM ينفصل خلال دقيقة، وتنتهي بالصراع مع الموسيقى بدلًا من الركوب عليها.","المقاطع المضمّنة في SynthFlow لها إيقاعات ونبضات أولى مقيسة، لذا يمكن للمشغّل بدء كل خطوة على \\"واحد\\" الموسيقى والحفاظ على محاذاة العدّات. المُنشئ يسرد المقاطع التي تناسب إيقاع القسم أولًا، بما في ذلك المقاطع بنصف أو ضِعف الإيقاع: مقطع بـ 140 BPM يحمل خطوة hoop بـ 70 BPM بشكل ممتاز.","الإيقاع المُولَّد يعمل بأي tempo. اختر طقمًا لقسم وسيقوم المشغّل بتوليف إيقاع يطابقه تمامًا، سواء كنت تؤدي سلّم tempo أو تمرينًا بطيئًا. وهو أيضًا الخيار الأفضل عندما تريد النبض دون أن تشد انتباهك اللحن.","يمكنك تحليل المقاطع من جهازك الخاص. يقدّر التطبيق الـ tempo والنبضة الأولى ويتيح لك التحقق منهما بالنقر مع الإيقاع. المقاطع ذات النبض الإلكتروني أو الصوتي الثابت تعمل بشكل أفضل؛ الموسيقى ذات تغيّرات الـ tempo أو rubato أو المقدمات الطويلة أصعب في القياس وأصعب في التدريب عليها.","بث الفيديو مُعطَّل أثناء التدريب المعدود لأن توقيته لا يمكن التحكم فيه بدقة. استخدمه للإحماء أو اللعب الحر بدلًا من ذلك، حيث لا يحتاج أي شيء إلى التزامن."]},"plateaus":{"title":"الهضاب والمنتصف الطويل","summary":"كل فنان flow يمر بأسابيع لا يتحسن فيها شيء؛ غيّر التمرين أو الـ tempo أو الأداة قبل تغيير الهدف.","imageAlt":"مجسّم ثلاثي الأبعاد يؤدي Mills Mess مع تقاطع الذراعين","body":["بداية الـ flow رائعة: شيء جديد كل جلسة. ثم، غالبًا في الوقت الذي تستطيع فيه أداء cascade ثابت أو إبقاء hoop مرتفعًا بلا نهاية، يبدو التقدم متوقفًا. هذا المنتصف الطويل هو حيث يستسلم معظم الناس، وحيث يحدث التعلم الأكثر إثارة للاهتمام.","الهضاب عادةً تكون تثبيتًا. جهازك العصبي يعيد تنظيم الحركة لتحتاج انتباهًا أقل، وهذا لا يظهر كحركات جديدة. غالبًا مهارة شعرت بأنها عالقة لأسبوعين تظهر فجأة في صباح ما. استمر في التدريب خلال الجزء المسطح.","غيّر التمرين، لا الهدف. إذا لم يزد الـ cascade سرعة، تدرّب عليه بـ tempo أقل مع قمم مثالية، ثم بعينيك على نقطة فوق النمط، ثم بيد واحدة فقط. إذا لم تأتِ حركة staff، قسّمها إلى نصفين وتدرّب على كل منهما على الإيقاع. التمارين الجديدة تمنح دماغك معلومات جديدة عن نفس المهارة.","التدريب المتقاطع. تعلّم أداة ثانية غالبًا ما يفتح الأولى. الـ hooping يحسّن الإيقاع خلف الـ juggling؛ العمل بالـ staff يعلّم المستويات التي تجعل حركات الـ hoop نظيفة. شجرة المكافآت لكل فن مستقلة، لذا التنويع لا يكلف تقدمًا أبدًا.","كن لطيفًا مع نفسك. قارن نفسك بالشهر الماضي، لا بالمؤدين على الإنترنت الذين تدرّبوا عشر سنوات. صفحة التقدم تحتفظ بسجل صادق للدقائق وأعلى tempos والحركات المتقنة. في أسبوع مسطح، انظر إليها وارَ كم ارتفع الخط بالفعل."]},"history-of-juggling":{"title":"تاريخ موجز للـ juggling","summary":"من لوحة مقبرة مصرية إلى jongleurs العصور الوسطى، ومسرح المنوعات، والرياضيات الحديثة.","imageAlt":"مجسّم ثلاثي الأبعاد يؤدي shower بثلاث كرات في دائرة","body":["الـ juggling قديم جدًا. من أقدم الصور المعروفة لوحة جدارية في مقبرة من الدولة الوسطى في بني حسن بمصر، عمرها نحو أربعة آلاف سنة، تُظهر نساءً يقذفن كرات. حسابات وصور من الصين واليونان وروما والمحيط الهادئ تشير إلى أن الناس في ثقافات كثيرة وجدوا طريقهم إلى الرمي والالتقاط للعرض واللعب.","في أوروبا في العصور الوسطى، كلمة jongleur، التي جاءت منها \\"juggler\\"، وصفت فناني الأداء المتجولين الذين غنّوا ورووا القصص وأدّوا الأكروبات وقذفوا الأشياء. كان الـ juggling مهارة من بين مهارات كثيرة، جزءًا من عدّة المؤدي بدلًا من كونه فنًا قائمًا بذاته.","مسارح المنوعات والسيرك في القرنين التاسع عشر وأوائل العشرين جعلت الـ juggling عرضًا رئيسيًا. تخصص المؤدون: jugglers النبلاء بالقبعات والعصي، وjugglers الهراوات، وjugglers الأرقام الذين يدفعون نحو سبع وثماني كرات وأكثر. إنريكو راستيلي، في أوائل القرن العشرين، لا يزال يُذكر غالبًا كواحد من أعظمهم.","من السبعينيات نمت ثقافة juggling كهواية حول الأندية والمهرجانات والمؤتمرات، مع مشاركة الناس للحركات بحرية. انضمت الرياضيات في الثمانينيات عندما منح تدوين siteswap الـ jugglers طريقة لكتابة الأنماط كأرقام، مما أدى إلى حركات جديدة اكتُشفت على الورق قبل أن يقذفها أحد.","اليوم يقف الـ juggling عند نقطة التقاء السيرك والرياضة والرقص والرياضيات. بعض الـ jugglers يتنافسون على الأرقام والتحمّل، وآخرون يؤدون choreography على الموسيقى، وآخرون يستكشفون الأنماط لذاتها. كل طريق يبدأ بنفس تبادل الكرتين، الذي يمكنك تعلمه هذا الأسبوع."]},"history-of-staff":{"title":"تدوير الـ staff: من سلاح إلى flow","summary":"عصي الفنون القتالية، وتحويل الـ baton، وأداء النار، كلها غذّت الـ spin staff الحديث.","imageAlt":"مجسّم ثلاثي الأبعاد يؤدي staff butterfly خلف الكتفين","body":["الـ staff واحدة من أقدم الأدوات الموجودة، وتدويرها مهارة قديمة. كثير من التقاليد القتالية تتدرب بعصا طويلة، منها bō الأوكيناوية، وgun الصينية، وقتال quarterstaff الأوروبي، وتمارينهم تشمل دورانات سريعة وتغييرات يد للدفاع والعرض معًا.","لتدوير الأداء جذور أخرى أيضًا. نما تحويل الـ baton إلى تخصص تنافسي في القرن العشرين، مع رميات ودحرجات ودورانات لا يزال الـ spinners يستعيرونها. المسرح والاستعراضات وأداء الشوارع حول العالم استخدمت عصيًا وأعمدة مدوّرة قبل وقت طويل من تسمية أي شخص لها flow.","ظهر مشهد عصا الفلو الحديث في أواخر القرن العشرين جنبًا إلى جنب مع عروض النار وثقافة المهرجانات. عصي النار، ذات الفتائل في كلا الطرفين، جعلت الدوران مرئيًا في الظلام ودفعت الفن نحو حركة سلسة ومتواصلة بدلًا من الضربات. لاحقًا جلبت عصي LED نفس المشهد البصري إلى الداخل.","في الوقت نفسه تقريبًا، بدأ فناني الفلو بوصف الدوران بنظرية مشتركة: المستويات، الدوران والدوران المضاد، العزل، التوقيت والاتجاه. كثير من ذلك تطور في مجتمع البوي وانتقل إلى العصا والهولا هوب والأدوات الأخرى، ولهذا تظهر نفس المصطلحات في كل أنحاء هذا التطبيق.","عصا الكونتاكت، حيث تتدحرج العصا على الجسم بدلًا من الإمساك بها، تطورت إلى أسلوب خاص مع تدحرجات على الرقبة والكتفين والذراعين. اليوم يتراوح دوران العصا من العرض القتالي إلى الكونتاكت فلو البطيء التأملي، وكلها مبنية على نفس دورة العجلة الأولى."]},"history-of-hoop":{"title":"الهولا هوب: من لعبة قديمة إلى فن الفلو","summary":"الهولا هوب كانت لعبة وأداة لآلاف السنين؛ جنون الخمسينيات وإحياء المهرجانات جعلا رقص الهولا هوب فنًا.","imageAlt":"شكل ثلاثي الأبعاد يمشي بالهولا هوب الدوارة على الجسم","body":["الهولا هوب من أقدم الألعاب. يُوصف أو يُصوَّر أطفال في مصر القديمة واليونان وروما وهم يدحرجون الهولا هوب بالعصي ويدورونها حول الجسم، وتظهر ألعاب الهولا هوب في ثقافات كثيرة منذ ذلك الحين.","تحمل الهولا هوب أيضًا معنى ثقافيًا عميقًا في بعض التقاليد. رقصة الهولا هوب التي تُؤدى في مجتمعات كثيرة من السكان الأصليين تستخدم عدة هولا هوب لبناء أشكال مثل الحيوانات والأرض، وتروي قصصًا من خلال الحركة. إنها تقليد حي بحد ذاته، مختلف عن مشهد الفلو الحديث، ويستحق التعلم عنه من ممارسيه أنفسهم.","جنون الهولا هوب البلاستيكية في أواخر الخمسينيات، مدفوعًا بإنتاج ضخم في الولايات المتحدة، وضع هولا هوب في ملايين المنازل بين ليلة وضحاها. لعقود بعد ذلك، كانت الهولا هوب تُرى غالبًا كلعبة أطفال وأداة لياقة.","من أواخر التسعينيات والألفينيات، بدأ البالغون في المهرجانات والمجتمعات الإلكترونية يعاملون الهولا هوب كشريك رقص. الهولا هوب الأكبر والأثقل المصنوعة يدويًا جعلت الدوران على الجسم أسهل للبالغين، بينما فتحت الهولا هوب الأصغر حركات سريعة خارج الجسم. نشرت الفيديوهات المشتركة مصطلحات مثل العزل والويدجي والإسكاليتور إلى ما هو أبعد من أي مدينة واحدة.","رقص الهولا هوب الحديث يستعير النظرية من العصا والبوي والإيقاع من كل نوع موسيقى. إنه سهل الوصول، مبهج وعميق: المبتدئ يمكنه إيجاد إيقاع الخصر في يوم، والخبير يمكنه قضاء سنوات في صقل عزل واحد."]},"fire-and-led":{"title":"أدوات النار وLED والعروض","summary":"أدوات العروض تغير الوزن والسرعة والمخاطر؛ تعلم كل حركة بأدوات التدريب أولًا وتدرب على النار بشكل منفصل.","imageAlt":"شكل ثلاثي الأبعاد يدور بالهولا هوب أفقيًا فوق الرأس مثل اللاسو","body":["مشاهدة عصا نار أو هولا هوب LED في الليل غالبًا ما تجذب الناس إلى الفلو. أدوات العروض رائعة، لكنها ليست نفس أدوات التدريب، والانتقال إليها يستحق خطة.","أدوات LED عادة أثقل من نسخ التدريب بسبب البطاريات والإلكترونيات. هذا يغير الزخم: الدورات تمتد أكثر، الرميات تبدو مختلفة، والمعصمان يعملان بجهد أكبر. تعلم كل حركة بأداة التدريب أولًا، ثم توقع فترة تكيف قصيرة على LED. اخفض الإيقاع في الجلسات الأولى.","عروض النار تخصص منفصل. التعامل مع الوقود، مناطق الدوران الآمنة، مراقبو السلامة مع بطانيات الحريق، الملابس المناسبة والقواعد المحلية كلها مهمة، والأفضل تعلمها شخصيًا من فناني نار ذوي خبرة. SynthFlow لا يعلّم النار، ولا شيء في التطبيق يجب التدرب عليه بأدوات مشتعلة.","قاعدة جيدة مستخدمة في مجتمعات فلو كثيرة هي أداء الحركة بأداة عرض فقط عندما تستطيع أداءها بثبات، مرات كثيرة متتالية، بأداة تدريب. تحت الأضواء أو اللهب لا مجال للتجارب.","العرض يغير أيضًا كيفية ترتيب التسلسل. الجمهور يقرأ المستويات الكبيرة، الانتقالات النظيفة ولحظات السكون الواضحة. ابنِ روتينات العرض في المنشئ مثل أي شيء آخر، عاينها، وتدرب على نفس الموسيقى كل مرة حتى تصبح العدّات تصميمًا حركيًا."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"اليوم الذي نجحت فيه الكاسكيد","summary":"ثلاثة أسابيع من مطاردة الكرات عبر الأرض انتهت في اللحظة التي توقفت فيها عن مراقبة يدي وبدأت العد.","body":["لمدة ثلاثة أسابيع، كاسكيد الثلاث كرات استمرت بالضبط أربع رميات. يمين، يسار، يمين، ثم كانت الكرة الثالثة في مكان ما خلف الأريكة. شاهدت فيديوهات، أبطأت، أسرعت. وقفت أمام السرير كما تقول كل الدروس. لم يتغير شيء، إلا مفرداتي.","الحل، عندما جاء، كان بسيطًا بشكل محرج. شغلت مقطعًا بإيقاع 90 BPM وقلت العدّات بصوت عالٍ: واحد، اثنان، ثلاثة، أربعة، رمية على كل نبضة. فجأة أصبح للرميات مكان تذهب إليه. بدلًا من الرمي عندما تشعر اليد بالاستعداد، أي عندما يخبرها الذعر بذلك، انتظرت كل رمية نبضتها. أصبح النمط أبطأ وأعلى وأهدأ.","الحل الثاني كان في مكان نظري. كنت أحدق في يدي، وهذا مثل قراءة كتاب بمراقبة جفونك. عندما رفعت نظري إلى القمم، النقطتين في أعلى الأقواس، بدأت يداي تلتقطان من تلقاء نفسها. القمم أخبرتني ما إذا كانت الرميات متساوية؛ اليدان لم تحتاجا إلى إشراف.","اثنتا عشرة رمية أصبحت عشرين، ثم خمسين. في إحدى الأمسيات تمكنت من التمرير خلال ثمانية بارات كاملة دون سقوط وابتسمت للسقف كالأبله. التطبيق سماها جولة نظيفة. أنا سميتها أول مرة يشعر فيها التمرير بالموسيقى بدلًا من الصراع.","إذا كنت عالقًا عند أربع رميات، جرب ما نجح معي: عُد بصوت عالٍ، ارمِ على النبضة، انظر إلى القمم. واسقط دون دراما. الأرض هي حيث يبدأ كل كاسكيد."]},"why-we-count-in-bars":{"title":"لماذا نعد بالبارات، لا بالثواني","summary":"ثبات أربعين ثانية منطقي لتمدد؛ نمط التمرير يعيش على نبضة، لذا نقيس التدريب بالبارات.","body":["عندما بدأنا بناء SynthFlow، كان أول قرار كبير هو كيفية قياس خطوة الروتين. تطبيقنا الشقيق SynthYoga يعد الثبات بالثواني والأنفاس. هذا يناسب وضعية تثبتها. لا يناسب نمطًا يتكرر على نبضة.","رمية التمرير، نصف دورة العصا ومدار الهولا هوب كلها دورات. إذا كانت الموسيقى على 100 BPM والكاسكيد على 103، فأنت لا تمرر على الموسيقى؛ بل تمرر قريبًا منها، وخلال دقيقة تكون متأخرًا بنبضة. قياس الخطوات بالبارات على إيقاع يعني أن الموسيقى والعدّات والشكل ثلاثي الأبعاد والخطوة التالية كلها تبدأ على نفس الداون بيت.","البارات أيضًا تجعل التقدم ملموسًا. «مرر لمدة دقيقة» غامض: دقيقة من ماذا، وبأي سرعة؟ «ثمانية بارات من الكاسكيد على 96 BPM» تحدٍ محدد وقابل للتكرار. إذا أنجزته بنظافة، يمكن للجلسة التالية أن تطلب 104. هكذا تعمل سلالم الإيقاع، ولهذا تعتمد الإتقان في التطبيق على الجولات النظيفة وليس الوقت فقط.","تطلب ذلك هندسة جادة. كل رسوم متحركة تُدار بنفس ساعة الصوت مثل الموسيقى، مجدولة مسبقًا حتى لا يتقطع شيء. المقاطع المضمنة لها إيقاعات وداون بيت مقاسة. الإيقاع المولّد يملأ أي إيقاع تختاره. المقاطع من جهازك تُحلل وتُفحص باختبار النقر. فيديو البث يُغلق في التدريب المعدود لأننا لا نستطيع إبقاءه على النبضة.","النتيجة أن النبضة تصبح معلمًا. عندما تنحرف، تسمعها. عندما تتقفل، تشعر بها. تبين أن العد بالبارات هو أهم قرار تصميمي اتخذناه."]},"staff-hit-me-in-the-head":{"title":"العصا ضربتني في رأسي (ودروس أخرى)","summary":"كل لاعب عصا يتلقى ضربات؛ الحشو والمستويات والصبر تحول الضربات إلى تقدم.","body":["أول شكل ثمانية لي انتهى بارتداد العصا عن جمجمتي ومغادرة الكلب للغرفة. الثاني انتهى بنفس الطريقة، بدون الكلب. إذا كنت تتعلم العصا، ستُضرب. السؤال هو كم بقوة، وماذا تتعلم منه.","الدرس الأول: الحشو ليس جبنًا. عصا تدريب بنهايات ناعمة حولت الضربات من صرخات إلى هزات كتف. هز الكتف مهم، لأن الخوف يجعلك تتوتر، والمعصم المتوتر يسحب العصا من مستواها، مما يسبب الضربة التالية.","الدرس الثاني: معظم الضربات تأتي من مستويات مائلة. عندما صوّرت نفسي من الجانب، رأيت العصا تميل نحو وجهي في أعلى كل دورة. كانت معصماي تتدحرجان للداخل. طبقة المستوى في العارض ثلاثي الأبعاد أظهرت النسخة النظيفة: العصا في مستوى مسطح بجانب الجسم، لا تميل للداخل أبدًا. إصلاح المعصم أصلح الضربات.","الدرس الثالث: البطيء والمعدود يتغلب على السريع والمتفائل. خفضت الإيقاع إلى أدنى نطاق الشكل ثمانية وعددت «الجانب الأيمن، الجانب الأيسر» مع الموسيقى. بهذه السرعة شعرت بتغيير اليد وحافظت على المستوى مسطحًا. بعد أسبوع تمكنت من العودة للأعلى.","الدرس الرابع: اضحك. دوران العصا سخيف ورائع. الضربات جزء من القصة التي يشاركها الجميع في المشهد. ارتدِ قبعة إذا احتجت، أخلِ أضواء السقف، واستمر في الدوران."]},"hooping-for-people-who-cant-hoop":{"title":"الهولا هوب لمن يظنون أنهم لا يستطيعون","summary":"معظم البالغين الذين «لا يستطيعون الهولا هوب» أُعطوا طوقًا بحجم لعبة؛ طوق أكبر ونبضة للأمام والخلف تحل معظم المشكلة.","body":["«لا أستطيع الهولا هوب» عبارة يسمعها مدربو الهولا باستمرار، عادةً من شخص جرب آخر مرة بطوق لعبة أطفال. الأطواق الصغيرة الخفيفة تدور بسرعة وتسقط بسرعة. تتطلب حركة ورك سريعة ومحمومة. البالغون مع طوق بحجم البالغين يجدونه غالبًا أسهل بكثير.","ابدأ كبيرًا. الطوق الذي يصل تقريبًا بين خصرك وصدرك عند وضعه على الأرض يدور ببطء كافٍ لتشعر بالإيقاع. الأطواق الأثقل تحمل أيضًا زخمًا أكبر. يمكنك الانتقال إلى الأصغر لاحقًا للسرعة وحركات خارج الجسم.","انبض، لا تدر دائرة. الخطأ الأكثر شيوعًا هو محاولة رسم دوائر كبيرة بالوركين. الهولا على الخصر عادةً حركة صغيرة للأمام والخلف، أو من جانب إلى جانب، بالتزامن مع الطوق. قدم واحدة للأمام قليلًا تساعد. الطوق يلمس أمامك وخلفك؛ تدفع بلطف عند مروره.","عُدّه. إيقاع مريح، دورة واحدة لكل نبضة، يمنح جسدك إيقاعًا يستقر عليه. التطبيق يبدأ الهولا على الخصر ببطء، ثم يتيح لك الصعود. إذا غاص الطوق، أضف قليلًا من السرعة لنبضتك، لا حركة أكبر.","توقع أن يسقط كثيرًا في بضع جلسات، ثم فجأة لا يسقط. الهولا من المهارات التي تُتقن دفعة واحدة. وعندما تحدث، ينتظرك عالم كامل من التدفق على الجسم وخارجه، وكثير منه لا يحتاج حتى الخصر."]},"unlocking-is-not-a-race":{"title":"الفتح ليس سباقًا","summary":"شجرة المكافآت تفتح حركات أصعب عند إتقان أساساتها؛ الهدف هو الأساسات.","body":["مكافآت SynthFlow هي الحركات. أتقن الـ cascade فيُفتح الـ reverse cascade؛ أتقن الـ front spin فيظهر الـ figure-8. من الممتع مشاهدة الشجرة تضيء، وقد صممناها لتكون كذلك. لكن في أي نظام فتح فخ، ويستحق التسمية.","الفخ هو التعامل مع الإتقان كمربع يُشطب. يمكنك تقنيًا تسجيل الجولات النظيفة لحركة في يوم جيد، وفتح التالية، والمضي قدمًا بأساس يعمل فقط عندما يسير كل شيء على ما يرام. عندها تبدو الحركات الأصعب مستحيلة، لأنها تفترض أن الأساس يعمل عندما تسوء الأمور.","الإتقان في التدفق يعني أن الحركة تصمد أمام التشتيت: قليل من التعب، إيقاع مختلف، شخص يمر. لهذا يطلب الإتقان جولات نظيفة عبر جلسات، لا في جلسة واحدة. ولهذا نقترح العودة إلى الحركات المتقنة بانتظام. الـ cascade ليس مستوى تنهيه؛ إنه الأرض التي تقف عليها شجرة الجgling كلها.","الحركات المقفلة لها صفحات أيضًا. يمكنك القراءة عنها، ومشاهدتها في 3D ورؤية ما تحتاجه. النظر إلى الأمام محفّز. التدرب على الأمام، بدون الأساسات، محبط في الغالب.","استمتع بالفتوحات، لكن قِس نفسك بمدى سهولة أقدم حركاتك. عندما يصبح الـ cascade مملًا، أنت جاهز للـ Mills Mess. عندما يصبح Mills Mess مملًا، الشجرة لديها المزيد لتقدمه."]},"practice-in-ten-minutes":{"title":"تدريب حقيقي في عشر دقائق","summary":"تسخين، حركة تركيز واحدة، رابط واحد، صعود إيقاع قصير وتهدئة: عشر دقائق، كل يوم.","body":["السبب الأكثر شيوعًا لعدم التدريب هو الوقت. الحقيقة أن مهارات التدفق تستجيب بشكل رائع للجلسات القصيرة المتكررة. إليك شكل العشر دقائق الذي نستخدمه أنفسنا.","الدقيقة 1 إلى 2: تسخين. دوائر المعصم، دوائر الذراع، لف الكتف، بضع دوائر ورك إذا كنت تستخدم الهولا. معدودة، بإيقاع مريح، ليستيقظ توقيتك مع مفاصلك.","الدقيقة 3 إلى 5: حركة التركيز. حركة واحدة تعمل عليها، بإيقاع تستطيع أداءها بنظافة. عدة خطوات قصيرة معدودة بدلًا من خطوة طويلة واحدة، مع نفس بينها.","الدقيقة 6 إلى 7: رابط واحد. اربط حركة التركيز بشيء تتدفق منه أو إليه. Cascade إلى reverse cascade. Front spin إلى figure-8. خصر إلى صدر. الروابط هي ما يجعل التدريب يبدو كتدفق بدلًا من تمارين.","الدقيقة 8 إلى 9: صعود إيقاع صغير. درجتان أو ثلاث، بضع BPM لكل واحدة، مع التوقف قبل أن ينكسر الشكل. انتهِ على درجة نظيفة.","الدقيقة 10: تهدئة. حركة بطيئة سهلة أو راحة قصيرة. سجّل جهدك. انتهيت.","عشر دقائق يوميًا أكثر من ساعة أسبوعيًا من التدريب المركّز، موزعة بالطريقة التي يحبها التنسيق الحركي. معالج التدريب يبني جلسات بهذا الحجم عندما تخبره أن وقتك ضيق، والروتينات القصيرة المدمجة تتبع نفس الشكل."]},"antispin-broke-my-brain":{"title":"الـ antispin كسر عقلي (لأسبوع)","summary":"تدوير العصا عكس دائرة اليد يبدو مستحيلًا حتى تمنح العدّات كل بتلة نبضة.","body":["الـ antispin هو حيث يبدأ تدوير العصا يبدو كواجب هندسة. يدك ترسم دائرة في اتجاه بينما تدور العصا في الاتجاه الآخر، والأطراف ترسم زهرة. أول مرة جربت، أنتجت شيئًا أشبه بهندباء ذابلة.","ما ساعد هو جعل الشكل قابلًا للعد. الـ antispin بأربع بتلات له أربع لحظات يشير فيها طرف مباشرة خارج الدائرة. أعطيت كل واحدة نبضة: أعلى، جانب، أسفل، جانب. ثم أبطأت الموسيقى كثيرًا تحت إيقاعي المعتاد واستهدفت ببساطة المواضع على النبضات.","الشبح في عارض 3D، الذي يُظهر أين يجب أن تكون العصا في النبضة التالية، كان أفضل صديق لي ذلك الأسبوع. وكذلك الأثر، الذي رسم زهرتي لأرى متى كانت البتلات غير متساوية. عادةً كانت البتلة السفلية مسحوقة، لأنني كنت أستعجل أسفل الدائرة.","بعد حوالي أسبوع، تغير شيء. توقفت عن التفكير في اليد والعصا كشيئين وبدأت أشعر بالزهرة كشكل واحد. عاد الإيقاع من تلقاء نفسه.","إذا كان الـ antispin يكسر عقلك، فهذا متوقع. أعطِ كل بتلة نبضة، أبطئ الموسيقى، ودع جسدك يحلها. إنه من أفضل الأحاسيس في التدفق عندما يحدث ذلك."]},"siteswaps-for-the-maths-shy":{"title":"الـ siteswap لغير محبي الرياضيات","summary":"لا تحتاج أن تحب الرياضيات لاستخدام siteswap؛ تحتاج فقط أن تعرف أن الأرقام الأكبر تذهب أعلى.","body":["تدوين siteswap له سمعة في تخويف الناس. سيقول الجglingرون بمرح «جرب 531» كأنه يشرح شيئًا. وهو يشرح، لكن فقط بعد معرفة أمرين، وهما أبسط مما يبدوان.","إليك كل ما تحتاجه تقريبًا. كل رقم هو رمية. الأرقام الأكبر تذهب أعلى. الأرقام الفردية تعبر إلى اليد الأخرى؛ الأرقام الزوجية تعود إلى نفس اليد. الـ 3 رمية cascade عادية. الـ 1 سحبة سريعة عبر. الـ 2 عادةً مجرد إمساك الكرة.","هذا يكفي لقراءة 441: رميتان أعلى تبقىان على جانبهما، ثم سحبة عبر. يمكنك الآن تجربتها دون قراءة كلمة أخرى. ارمِ، ارمِ، اسحب، على النبضة.","إذا أردت قطعة أخرى: اجمع الأرقام واقسم على عددها، تحصل على عدد الكرات. 4 + 4 + 1 = 9، مقسومًا على 3 يساوي 3 كرات. إذا لم تكن النتيجة عددًا صحيحًا، لا يمكن أداء النمط. هذه هي نظرية المتوسط الشهيرة بأكملها.","في SynthFlow، كل حركة جgling لها siteswap، ومحرك 3D يحرك مباشرة منه. هذا يعني أن الشكل يرمي دائمًا الارتفاعات التي تصفها الأرقام بالضبط، على النبضات الدقيقة. مشاهدة siteswap متحركًا ببطء هي أسرع طريقة نعرفها لجعل الأرقام منطقية. لا حاجة لشهادة رياضيات."]},"music-that-fights-you":{"title":"عندما تعاندك الموسيقى","summary":"مقطع ينحرف ضد العدّات يجعل كل حركة أصعب؛ الإيقاعات المقيسة والنبضات المولّدة تحل ذلك.","body":["ربما شعرت بها: أغنية تحبها، حركة تعرفها، وبشكل ما كل شيء يبدو خطأ. تستعجل، تسقط، تلوم نفسك. غالبًا المشكلة ليست فيك. إنها أن إيقاع الأغنية لا يطابق الحركة.","كل حركة فلو لها نطاق إيقاع مريح. تحته، تتوقف الأدوات الدوارة؛ وفوقه، تصبح الرميات منخفضة ومحمومة. مقطع بإيقاع 128 BPM تحت حركة هوب تحب 90 يجعلك تختار بين الموسيقى والهوب. الخبر الجيد أن نصف الوقت والضعف يساعدان: 128 يمكن أن يحمل حركة عند 64، دورة واحدة كل نبضتين.","الانحراف هو المشكلة الأكثر خفاءً. إذا قالت الموسيقى 120 لكن العدّ قال 116، ينزلق الاثنان بعيدًا خلال دقيقة، ولا يستطيع جسمك متابعة كليهما. لهذا يستخدم SynthFlow إيقاعات مقيسة لمقاطعه المضمنة، ويولّد إيقاعًا في أي tempo دقيق، ويفحص المقاطع من جهازك باختبار النقر.","عندما يقاتلك مقطع، لا تقاتل بالمقابل. بدّل إلى الإيقاع المولّد للخطوة، أو دع المنشئ يقترح مقطعًا في النطاق الصحيح. احتفظ بالأغاني التي تحبها للعب الحر، حيث لا يحتاج شيء إلى التطابق.","يجب أن تشعر الموسيقى كأنها شريك. إذا شعرت أنها خصم، غيّر الموسيقى، لا حركتك."]},"learning-alongside-my-kid":{"title":"تعلمت الجgling بجانب طفلي","summary":"مبتدئان، كيس كرات وقاعدة واحدة: نحتفل بالسقطات بصوت عالٍ مثل الالتقاطات.","body":["طلبت ابنتي تعلم الجgling، وأدركت أنني لا أستطيع الجgling أيضًا. فتعلمنا معًا، عشر دقائق بعد العشاء، بثلاث كرات فاصولياء لكل منا وقاعدة واحدة: نهتف للسقطات بصوت عالٍ مثل الالتقاطات.","تبدو القاعدة سخيفة. لكنها كانت الجزء الأهم. الأطفال، والبالغون، يتوترون عندما يظنون أن الخطأ محرج. التوتر يجعل الرميات أسوأ. الهتاف لكل سقطة جعل الأرضية جزءًا من اللعبة وأبقانا مرتاحين.","بدأنا بكركة واحدة، نقذفها من يد إلى يد على الإيقاع، بقمم في مستوى العين. بدا الأمر سهلًا جدًا لثلاث جلسات ثم أصبح مهمًا فجأة، لأن تبادل الكركتين يعمل فقط إذا كانت تلك الرميات الفردية ثابتة. تعلمت التبادل قبلي وكانت لا تُطاق بشأن ذلك.","ساعدتنا الموسيقى المعدودة على التدرب معًا. نفس tempo، نفس الضربة الأولى، شخصان يقذفان في الوقت. عندما فقد أحدنا النمط، استمر الآخر، وعاد المُسقط في «واحد» التالي.","بعد أربعة أسابيع، لدينا كلانا cascade متذبذب. والأهم، لدينا عادة نتطلع إليها كلانا. إذا كان لديك طفل يريد تعلم شيء، تعلمه معه. أن تكون مبتدئًا معًا أمر لا يُقدّر بثمن."]},"why-your-throws-drift-forward":{"title":"لماذا تنحرف رمياتك إلى الأمام","summary":"إذا أنهيت كل cascade على بُعد ثلاث خطوات من حيث بدأت، فرمياتك تميل بعيدًا عنك. إليك كيف تعيدها إلى البيت.","body":["كل لاعب juggling يعرف المشية. تبدأ الـ cascade في وسط الغرفة وتنهيها وأنفك ملتصق بالجدار، تطارد النمط خطوة بخطوة. يبدو وكأن الكرات تسحبك. لكنها لا تفعل. أنت ترميها إلى الأمام، بضعة سنتيمترات في كل مرة، ثم تمشي لتلحق بها.","السبب دائمًا تقريبًا هو المرفقان. عندما تتوتر، تنحرف الساعدان إلى الأمام وتُفلت اليدان الكرة قبل الجسم قليلًا. كل رمية تهبط أبعد قليلًا، فتصير الالتقاطة التالية أبعد قليلًا، فتبدأ الرمية التالية أبعد قليلًا. يتراكم الأمر بسرعة.","أول إصلاح أعلّمه هو ضمّ المرفقين. أبقِ المرفقين قرب الأضلاع، والساعدين أفقيين تقريبًا، وارمِ الكرات مستقيمة إلى الأعلى بمحاذاة عينيك لا إلى الأمام. يبدو ضيقًا في اليوم الأول. ثم يصبح هادئًا.","الإصلاح الثاني هو الجدار. قف مواجهًا له على مسافة ساعد تقريبًا، وابدأ الـ juggling. إذا انحرفت الرميات، سيخبرك الجدار فورًا وبصوت عالٍ. عشر دقائق من التدريب على الجدار تعلّم الجسم كيف يبدو النمط المستقيم أسرع من أي كلام أقوله.","يراقب وضع الكاميرا في SynthFlow الانحراف أيضًا. يتتبع مقدار ما يبدو جذعك أكبر للكاميرا خلال خطوة، أي أنك تمشي نحوها، وينبّهك بإشارة قصيرة. يمكن للمدرب ثلاثي الأبعاد أيضًا أن يعرض شبح رمية أمامية بجانب الرمية النظيفة، لترى الفرق لا أن تسمع عنه فقط.","الانحراف ليس عيبًا في شخصيتك. إنه عادة توتر، والعادات تتغير بالتكرار. اضمم المرفقين، وارمِ إلى الأعلى لا إلى الأمام، ودع الجدار يبقيك صادقًا."]},"practising-to-a-click":{"title":"التدريب على النقرة","summary":"يبدو الميترونوم أقل شيء ممتع في العالم. لكنه تبيّن أنه الشيء الذي جعل flow لديّ يشبه الرقص.","body":["قاومت النقرة لسنوات. كانت الموسيقى هي جوهر flow arts بالنسبة لي، وكان الميترونوم يبدو كواجب مدرسي. ثم شاهدني صديق يعزف الطبول وأنا ألعب الـ juggling وقال بلطف إنني أتسارع كلما تحمست وأتباطأ كلما خفت. كانت محقة، ولم يكن لديّ أي فكرة.","فجرّبت أسبوعًا من التدريب على النقرة فقط. الاكتشاف الأول كان أن النبض الثابت أصعب مما يبدو. نمط الكرتين في يد واحدة أراد الاندفاع. وfigure-8 بالعصا أراد التباطؤ في الجانب الضعيف. النقرة لا تهتم بمشاعري؛ إنها تحافظ على الإيقاع فقط.","الاكتشاف الثاني كان أن النقرة جعلت الموسيقى أسهل. بعد أسبوع، عندما أعدت تشغيل المقاطع الحقيقية، صرت أشعر أين يجلس الإيقاع داخل الصوت. توقفت عن مصارعة الأغاني ذات التوقيت المرن وبدأت أختار أي جزء من الـ groove أثبّت عليه.","الإيقاع المُولَّد في SynthFlow نسخة ألطف من النقرة. تختار kit، من نقرة بسيطة إلى طبول يدوية، فيعزف بأي tempo، ليتمكن النمط من العيش بالسرعة التي تستطيع الحفاظ عليها بالضبط. يمكنه أيضًا أن يعمل بهدوء تحت مقطع موسيقي كدليل. ما زلت أستخدمه وحده في الدقائق الأولى من كل جلسة.","إذا أردت تجربة هذا، اختر نمطًا واحدًا وtempo واحدًا يبدو أبطأ قليلًا مما ينبغي. عُدّ بصوت عالٍ لأربعة bars، ثم توقف عن العد واستمع فقط. عندما يبدو النمط والنقرة كصوت واحد، أضف أربع BPM. هذه هي الطريقة كلها."]},"staff-in-a-small-apartment":{"title":"العصا في شقة صغيرة","summary":"عصا بطول 1.4 متر وسقف بارتفاع 2.4 متر يمكنهما التعايش. عليك فقط اختيار مستوياتك.","body":["شقتي ذات أسقف منخفضة، وتركيبة إضاءة أحبها، وجار في الطابق السفلي يعمل ليلًا. لا شيء من هذا مثالي لتدوير العصا. تدربت في الحدائق لمدة عام قبل أن أكتشف أن معظم تدريبي يمكن أن يحدث في الداخل بعد كل شيء.","الحيلة هي المستويات. دورانات wheel-plane، الكبيرة بجانب الجسم، تحتاج كامل ارتفاع العصا فوق رأسك. عمل wall-plane أمام الجسم يحتاج عرضًا لكن ارتفاعًا أقل. دورانات floor-plane، مثل الهليكوبتر، تحتاج مساحة فوق رأسك لكن لا شيء حول ساقيك. كل غرفة تدعم حركات مختلفة.","في غرفة معيشتي أستطيع أداء isolations وfront spins وfigure-8 بطيئة وذراعاي منخفضتان. في الممر لا أستطيع فعل أي شيء، لذا الممر لتسخين الرسغين. غرفة النوم فيها أعلى سقف، لذا عمل wheel-plane يحدث هناك، ببطء، مع إزالة تركيبة الإضاءة وتخزينها في درج.","العصي القصيرة تساعد أيضًا. عصا تدريب أقصر بطول كف من عصا الأداء حوّلت الكثير من الإخفاقات الوشيكة إلى مساحة مريحة. يتغير التوقيت قليلًا، لذا أتفقد عصاي بالطول الكامل في الخارج مرة أسبوعيًا.","من أجل الجيران: حصائر تدريب وعصي بأطراف ناعمة. سقوط على حصيرة يوغا يصدر صوتًا مكتومًا بدلًا من فرقعة. أيضًا أُبقي جلسات الداخل على روتينات معدودة من عشر دقائق، ما يجعل الضجيج قصيرًا والتدريب مركّزًا.","يتيح لك SynthFlow تعليم الحركات التي لا تستطيع أداءها في المنزل كغير مرغوبة ليستبعدها المولّد من الروتينات الداخلية. المساحات الصغيرة لا توقف التقدم. إنها فقط تجعلك بارعًا جدًا في isolations."]},"hooping-after-40":{"title":"الهولا هوب بعد الأربعين","summary":"أمسكت الهولا هوب لأول مرة في سن 43. كان لظهري وركبتيّ وكبريائي آراء. إليك ما نجح.","body":["اشتريت أول هولا هوب للبالغين بنزوة بعد مهرجان، مقتنعًا أنني سأكون فظيعًا. كنت فظيعًا. وكنت أيضًا، خلال شهر، ألعب بالهولا هوب على خصري لأغانٍ كاملة، وخلال ستة أشهر أؤدي حركات بسيطة بعيدًا عن الجسم. العمر لم يوقفني. غيّر فقط كيف احتجت أن أتدرب.","الدرس الكبير كان الإحماء الجيد. دوائر الورك ولفّ الجذع وثنيات الركبتين اللطيفة تستغرق ثلاث دقائق وتجعل أول هولا هوب في الجلسة سلسًا بدلًا من متصلب. يضع SynthFlow الإحماء في بداية كل روتين لسبب، وتوقفت عن تخطيه بعد صباح واحد متيبس.","الدرس الثاني كان حجم الهولا هوب. الهولا هوب الأكبر والأثقل قليلًا يدور أبطأ، ما يمنحك وقتًا أكثر ويطلب جهدًا أقل من أسفل الظهر. بدأت بهولا هوب يصل بين خصري وصدرى عند وضعه على الأرض، وما زلت أستخدمه لجلسات التدريب الطويلة.","الثالث: نبّض، لا تدُر. غالبًا ما يحرّك المبتدئون الوركين في دائرة، ما يلفّ العمود الفقري أكثر مما يحتاج. نبض أمامي وخلفي، أو جانبي إذا دار الهولا هوب بهذا الاتجاه عندك، يبقي الهولا هوب مرتفعًا بجهد أقل. يوضح المدرب ثلاثي الأبعاد هذا بوضوح إذا راقبت الوركين لا الهولا هوب.","أخيرًا، القصير والمتكرر يتغلب على الطويل والعرضي. عشر دقائق أربع مرات أسبوعيًا فعلت لي أكثر من ساعة يوم الأحد. جسمي تعافى بين الجلسات، والحركات ثبتت.","إذا كنت فوق الأربعين وفضوليًا، ابدأ. الهولا هوب لا يعرف كم عمرك."]},"fire-and-the-beginner":{"title":"النار والمبتدئ","summary":"تدوير النار هو الجزء الأكثر ظهورًا في flow arts والجزء الذي يسأل عنه المبتدئون أكثر. الجواب الصادق هو: ليس بعد، وليس وحدك.","body":["كل أسبوع يسألنا أحدهم متى سيعلم SynthFlow النار. سؤال عادل. النار جميلة، وكثير من اللاعبين دخلوا المجال بعد رؤية دائرة نار في الليل. لكننا لن نعلّم أحدًا أبدًا إشعال أداة، وهذا المنشور يشرح السبب.","تضيف النار مخاطر لا علاقة لها بالمهارة: التعامل مع الوقود، الملابس، الرياح، المتفرجون، الحروق والإطفاء. هذه تُتعلَّم من أشخاص ذوي خبرة وجهًا لوجه، بحضور شخص سلامة مدرّب ومعدات مناسبة جاهزة. لا يستطيع تطبيق أن يتحقق من حوض الوقود أو ملابسك القطنية أو منشفتك الآمنة.","ما يستطيع التطبيق فعله هو مساعدتك على بناء المهارات التي تحتاجها النار قبل أن تقترب منها أصلًا. هذا يعني حركات تؤديها بثبات لأغنية كاملة، بtempo ثابت، دون سقوط. إذا كان النمط لا يزال يفاجئك في المنزل بأداة تدريب، فهو ليس جاهزًا للنار.","اختبار مفيد من مجتمع النار: هل تستطيع أداء الروتين وعيناك نصف مغمضتين، في الظلام، بينما يتحدث إليك أحدهم؟ النار ساطعة وساخنة وصاخبة، وتأخذ انتباهك. يجب أن يعرف جسمك الحركات دون إشراف.","أدوات LED خطوة رائعة بينهما. تمنحك مظهر الليل، والخطوط الضوئية، وتفاعل الجمهور دون المخاطرة. يعرض LED style pack في SynthFlow كيف ستبدو أنماطك مضاءة، وهي أيضًا طريقة جيدة لرصد المستويات المهملة.","عندما تكون مستعدًا، ابحث عن تجمع نار محلي، قدّم نفسك، واطلب تعلم السلامة أولاً. تدرّب بأدوات تدريب حتى ذلك الحين. النار ستظل هناك."]},"four-balls-taught-me-patience":{"title":"أربع كرات علّمتني الصبر","summary":"الانتقال من ثلاث كرات إلى أربع استغرق مني وقتًا أطول من تعلم الثلاث من الأساس، وغيّر طريقة تفكيري في التدريب.","body":["ثلاث كرات استغرقت خمسة أسابيع. أربع استغرقت خمسة أشهر. لم يحذرني أحد من هذا، لذا أحذرك: أربع كرات ليست ثلاث كرات زائد واحدة. إنها نمط مختلف تمامًا، وجسمك يجب أن يتعلمه من الصفر.","في نافورة الأربع كرات، كل يد تتعامل مع كرتين بمفردها، والكرات لا تتقاطع أبدًا. اليدان عادةً تتبادلان، لكن لا يوجد تبادل بينهما على الإطلاق. كل ما تعلمته عن التقاط كرة من اليد الأخرى أصبح فجأة بلا فائدة.","لذا عدت إلى يد واحدة. كرتان في اليد اليمنى، في أعمدة، ثم دوائر، حتى استطعت أداء خمسين رمية دون تفكير. ثم اليد اليسرى، التي استغرقت ثلاثة أضعاف الوقت. ثم كلتا اليدين معًا، أولاً بالتزامن، ثم بالتبادل. ساعدني سلّم الإيقاع في SynthFlow هنا: بدأت كل أسبوع من أسفل نطاق النافورة ولم أتقدم إلا بعد جولة نظيفة.","درس الصبر جاء من فترات الثبات. بعض الأسابيع لم يتحسن شيء. سجّلت السقطات والجولات النظيفة على أي حال، وأظهر الرسم البياني تقدمًا بطيئًا حتى عندما شعرت أنه لا يوجد. البيانات جعلت الأسابيع المملة محتملة.","الدرس الآخر كان عن الراحة. أربع كرات أرهقت ساعديّ بطريقة لم تفعلها الثلاث أبدًا. عندما تدربت كل يوم، أصبحت أسوأ. عندما تدربت يومًا بعد يوم، تحسنت. عضلات القبضة تحتاج للتعافي مثل أي عضلات أخرى.","إذا كنت عالقًا بين الثلاث والأربع، قسّم المشكلة، ثق بالأسابيع البطيئة، وأعطِ ساعديك يوم راحة. إنها تأتي فعلًا."]},"the-escalator-and-hand-traffic":{"title":"السلم الكهربائي وفن حركة اليدين","summary":"حركات اليد بالهولا هوب تبدو كالسحر حتى ترى أنها مجرد إدارة دقيقة لحركة اليدين.","body":["أول مرة رأيت فيها escalator، بدا الهولا هوب وكأنه يتسلق ذراعي اللاعب ويطفو للأسفل مجددًا، بلا نهاية، دون قبضة واضحة. افترضت أنه يحتاج سنوات من التدريب. احتاج حوالي ثلاثة أسابيع، بعد أن فهمت أنه مجرد نمط من عمليات التسليم.","تقريبًا كل حركة هولا هوب خارج الجسم تتعلق بأي يد تمسك الهولا هوب، ومتى تفلت، وأين تلتقي اليد الأخرى به. إذا كان التوقيت بين اليدين غير واضح، يتذبذب الهولا هوب خارج مستواه وتنهار الحركة. إذا كان التوقيت نظيفًا، يبدو الهولا هوب وكأنه يتحرك من تلقاء نفسه.","لذا بدأت بتسمية عمليات التسليم. على عدّ SynthFlow كنت أنطق اليدين بصوت عالٍ بدلاً من الأرقام: يمين، يسار، يمين، يسار، واحدة على كل نبضة. نطقها مع الموسيقى أجبرني على ملاحظة عندما تمسك يدي اليسرى مبكرًا. الإمساك المبكر كان مصدر كل تذبذب تقريبًا.","المفتاح الثاني كان الحفاظ على الهولا هوب في مستواه. اليد التي تلتف أثناء الإمساك تميل الهولا هوب، والهولا هوب المائل يسقط بعد نصف ثانية. يساعد هنا تراكب المستوى، وكذلك التدريب أمام مرآة بإيقاعات بطيئة.","بمجرد أن أصبح escalator موثوقًا، جاءت حركات اليد الأخرى أسرع. العزل والتمريرات والlasso كلها تستخدم نفس الفكرة: تسليمات واضحة، مستويات مسطحة، توقيت ثابت. السحر مجرد إدارة حركة."]},"behind-the-back-without-fear":{"title":"خلف الظهر بدون خوف","summary":"تمريرات العصا خلف الظهر هي حيث يتوقف معظم اللاعبين. المشكلة عادةً ليست المهارة بل الرغبة في النظر.","body":["لأشهر كانت تمريرتي خلف الظهر مجرد تمريرة أمامية مع لفّة متفائلة. أبدأ الحركة، أذعر عندما تخرج العصا من مجال رؤيتي، وأعيدها أمامي. العصا لم تذهب فعلاً خلف ظهري أبدًا. عقلي لم يسمح بذلك.","جاء الاختراق من تقبّل أنني لا أستطيع رؤية الحركة. لا يمكنك مشاهدة تمريرة خلف الظهر. عليك أن تشعر بمكان العصا من اليد التي تفلت وتثق باليد التي تنتظر.","درّبت ذلك الإحساس بالحركة البطيئة. بدون دوران على الإطلاق، مررت العصا خلف ظهري، من يد إلى يد، وعيناي للأمام. ثم مع نصف لفّة بطيئة أولاً. ثم عند أدنى نطاق إيقاع الحركة، مع العدّ. كل خطوة بدت سخيفة. كل خطوة نجحت.","كان المدرب ثلاثي الأبعاد مفيدًا بشكل مفاجئ لأنني استطعت تدوير العرض ومشاهدة الحركة من الخلف. رؤية أين تلتقي اليدان، وكيف تبقى العصا في مستوى الجدار أثناء دورانها، أعطت جسدي خريطة لم يستطع الحصول عليها من الأمام.","الخوف الثاني كان ضرب نفسي. عصا تدريب بطرف ناعم ومساحة واسعة واضحة حلّا ذلك. بمجرد أن عرفت أن الخطأ سيكلفني ارتطامًا لطيفًا بدلاً من كدمة، توقفت عن التفلطح، والتفلطح كان يسبب الأخطاء.","إذا كان خلف الظهر لا يزال يخيفك، أبطئه كثيرًا، أزل الدوران، وأبقِ عينيك للأمام. يداك تعرفان أكثر مما تظن."]},"why-reverse-feels-wrong":{"title":"لماذا يبدو reverse cascade خاطئًا","summary":"reverse cascade يستخدم نفس اليدين، ونفس الكرات، ونفس الإيقاع كcascade. فلماذا يبدو وكأنك تبدأ من جديد؟","body":["عندما تعلمت reverse cascade، توقعت أن يستغرق بعد الظهر. إنها نفس الثلاث كرات، ونفس تبادل اليدين، ونفس إيقاع cascade. استغرق ثلاثة أسابيع، ولم أستطع فهم السبب.","الجواب هو الاتجاه. في cascade العادي، تُرمى كل كرة من داخل النمط وتُلتقط من الخارج. في reverse cascade، تُرمى الكرة من الخارج، فوق الكرة القادمة، وتُلتقط من الداخل. يداك تصنعان نفس الإيقاع لكن أشكالاً مختلفة تمامًا.","الشكل الجديد يكسر توقيتك. في cascade، ترمي تمامًا عندما تبدأ الكرة القادمة بالسقوط. في reverse، تحتاج للرمي أبكر قليلاً حتى تتجاوز كرتك قمة الأخرى. ارمِ في اللحظة القديمة وستتصادم الكرات.","أصلحتها بكرتين أولاً. كرتان، اتجاه معاكس، مع العدّ على النبضة، حتى أصبحت تلقائية. ثم ثلاث كرات بإيقاع بطيء مع نطق العدّ بصوت عالٍ. أظهر لي تراكب الشبح في SynthFlow خطأً نموذجيًا، رمية منخفضة جدًا تصطدم بالكرة الأخرى، واستطعت رؤية أنني أفعل ذلك بالضبط.","بمجرد أن فهمتها، فتحت الكثير. خلط cascade وreverse هو أساس العديد من الحركات، والشكل المعاكس يظهر مجددًا في Mills Mess. كوني سيئًا فيها لثلاثة أسابيع كان يستحق ذلك."]},"making-a-prop-stand-still":{"title":"العزل: جعل الأداة تبقى ثابتة","summary":"العزل هو حركة تبدو فيها الأداة وكأنها تبقى في مكان واحد بينما تتحرك أنت حولها. إنه أكثر خدعة مُرضية في فنون الفلو.","body":["أول مرة أتقنت فيها عزل العصا، سألني صديقي كيف تطفو العصا. لم تكن تطفو بالطبع. كانت يداي تتحركان في دائرة دقيقة بحيث تبقى نقطة واحدة على العصا ثابتة في الهواء. لكن من الخارج بدا مستحيلاً، وذلك الشعور هو سبب حبي للعزل.","كل عزل يعمل بنفس الطريقة. اختر نقطة على الأداة، عادةً المركز أو أحد الطرفين، وأبقِ تلك النقطة ثابتة بينما تدور بقية الأداة. يجب أن تتحرك يداك في الاتجاه المعاكس تمامًا لما تريد الأداة فعله. إنه غير بديهي ومُنوّم قليلاً.","أصعب جزء هو أن جسمك يتحرك أيضًا. الوركان ينزاحان، الكتفان يدوران، وكل حركة صغيرة تظهر كتذبذب في النقطة الثابتة. تدربت أمام مرآة مع قطعة لاصق على الزجاج تحدد مكان النقطة الثابتة. إذا خرج مركز الأداة عن اللاصق، عرفت.","عزل الهولا هوب يتبع نفس الفكرة. في SynthFlow أشغّل الآثار في العارض ثلاثي الأبعاد وأشاهد المدرب: في عزل نظيف، يبقى الأثر حول النقطة الثابتة صغيرًا جدًا. عندما أبطأت الإيقاع كثيرًا وقلّدته، استطعت الشعور بيديّ تنزلقان عند قمة كل دائرة.","العزل يبني أيضًا تحكمًا يساعد كل شيء آخر. بمجرد أن تستطيع إبقاء الأداة ثابتة، يمكنك وضعها في أي مكان تختاره. تصبح المستويات أكثر تسطحًا، والانتقالات أنظف، ويبدأ فلوّك يبدو مقصودًا لا محظوظًا.","ابدأ ببطء، حدد النقطة الثابتة، وراقبها كالصقر. ثم أرِ صديقًا واستمتع بوجهه."]}}`),i={"zero-to-cascade":{name:`من الصفر إلى cascade في 4 أسابيع`,description:`كركة واحدة، ثم اثنتان، ثم تنضم الثالثة. جلسة قصيرة يوميًا تكفي: أكمل روتين كل أسبوع لإتقان حركته وافتح التالي.`,weeks:[{label:`الأسبوع 1 · كركة واحدة`},{label:`الأسبوع 2 · كركتان`},{label:`الأسبوع 3 · الكركة الثالثة`},{label:`الأسبوع 4 · Cascade`}]},"staff-foundations":{name:`أساسيات الستاف`,description:`الدوران العجلي والأمامي، الشكل 8 والتمرير: الحركات الأربع التي تُبنى منها تقريبًا كل حركة ستاف.`,weeks:[{label:`الأسبوع 1 · Wheel spin`},{label:`الأسبوع 2 · Front spin`},{label:`الأسبوع 3 · Figure 8`},{label:`الأسبوع 4 · Pass-through`}]},"off-body-hoop":{name:`هوب خارج الجسم`,description:`من تدوير الهوب على يد واحدة إلى lassos وpasses وwedgies وisolation التي تجعل الهوب يبدو كأنه يطفو.`,weeks:[{label:`الأسبوع 1 · Hand spin`},{label:`الأسبوع 2 · Lasso وpass`},{label:`الأسبوع 3 · Wedgie`},{label:`الأسبوع 4 · Isolation`}]}},a={"sf-ambient-70":{name:`دوران بطيء`},"sf-world-75":{name:`خطوات السوق`},"sf-ambient-80":{name:`انسياب الفانوس`},"sf-world-85":{name:`عجلة الصحراء`},"sf-handdrum-90":{name:`طبل الدائرة`},"sf-funk-95":{name:`معصمان مرتخيان`},"sf-handdrum-100":{name:`أيادي ضوء النار`},"sf-world-105":{name:`أجراس النهر`},"sf-funk-110":{name:`كاسكيد الجيب`},"sf-handdrum-115":{name:`إيقاع الساحة`},"sf-electronic-120":{name:`عصا النيون`},"sf-funk-125":{name:`نمط الارتداد`},"sf-electronic-130":{name:`هولا بكسل`},"sf-handdrum-135":{name:`دجمبي الغروب`},"sf-electronic-140":{name:`مسارات LED`},"sf-funk-145":{name:`دورة الدوران`},"sf-electronic-150":{name:`تدفق ستروب`},"sf-handdrum-155":{name:`راحتا اليد السريعتان`},"sf-electronic-160":{name:`دوار الليل`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};